insert into public.exercise_translations_gymtrack (exercisedb_id, name_pt, instructions_pt) values
  ('01qpYSe', 'Cachorro olhou para cima', array['Posicione-se de bruços no chão com as pernas estendidas para trás', 'Apoie as mãos no chão ao lado das costelas inferiores com os dedos apontados para a frente', 'Entre na posição inicial e respire calmamente antes de aprofundar o movimento', 'Avance em direção ao alongamento até sentir uma tensão leve; continue respirando e evite balançar', 'Mantenha-se em um alongamento leve em vez de puxar mais com impulso', 'Mantenha a posição com respiração constante e solte devagar; repita do outro lado se necessário']),
  ('03lzqwk', 'Elevação de joelhos pendurado com assistência', array['Suspenda-se em uma barra fixa com os braços estendidos e as palmas viradas para a frente', 'Contraia os músculos do tronco e eleve os joelhos em direção ao peito, flexionando os quadris e os joelhos', 'Contraia o abdômen e mantenha os ombros fixos no apoio', 'Eleve as pernas contraindo o tronco e movimentando os quadris em vez de balançar', 'Desacelere as pernas antes que elas tirem a região lombar da posição correta', 'Abaixe as pernas devagar sem balançar ou perder a posição do tronco']),
  ('05Cf2v8', 'Mergulho nas paralelas', array['Posicione-se entre duas barras paralelas com os braços estendidos e o corpo suspenso no ar', 'Antes de se mover, flexione os joelhos e cruze os tornozelos', 'Abaixe os ombros e mantenha os cotovelos apontados principalmente para trás', 'Flexione os cotovelos para descer entre os apoios; pare em uma profundidade confortável para os ombros', 'Escolha uma profundidade que permita manter os ombros confortáveis', 'Empurre com as mãos para subir e ajuste os ombros antes de outra repetição']),
  ('0br45wL', 'Flexão com chute interno de perna', array['Comece em uma posição de flexão com as mãos logo além da largura dos ombros e os pés juntos', 'Abaixe o corpo em direção ao chão flexionando os cotovelos, com a coluna firme e o core contraído', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito mantendo o corpo em uma linha reta', 'Mantenha a cabeça alinhada com a coluna conforme os cotovelos flexionam', 'Empurre de volta para os braços estendidos, mantendo a linha do corpo intacta']),
  ('0CXGHya', 'Crucifixo no cabo', array['Ajuste as polias do cabo na altura do peito', 'Posicione-se no centro da máquina de cabo com um pé na frente do outro', 'Mantenha uma leve flexão nos cotovelos e ajuste os ombros antes de mover os braços', 'Traga os puxadores pela frente do peito em um arco amplo, mantendo uma leve flexão nos cotovelos', 'Mantenha o ângulo do cotovelo quase inalterado durante o arco', 'Abra os braços de volta pelo mesmo arco sem deixar a carga cair']),
  ('0dCyly0', 'Desenvolvimento Bradford sentado com barra', array['Sente-se em um banco com as costas retas e os pés apoiados no chão', 'Segure a barra com as palmas viradas para baixo, logo além da largura dos ombros', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores para longe enquanto mantém o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('0I5fUyn', 'Puxada com pegada supinada com elástico', array['Conecte o elástico a um ponto de ancoragem alto, como uma barra fixa ou viga firme', 'Fique de frente para o ponto de ancoragem em uma base estável com os pés na largura dos ombros', 'Sente-se erguido e ajuste os ombros antes de puxar o puxador para baixo', 'Puxe o puxador para baixo direcionando os cotovelos em direção às costelas; mantenha o tronco firme', 'Controle o elástico na volta em vez de deixar que ele puxe você de volta', 'Deixe o puxador subir de forma constante até que os braços estejam compridos e ajuste os ombros']),
  ('0IgNjSM', 'Rosca direta invertida em pé com halteres', array['Fique em pé com os pés na largura dos ombros e segure um halter em cada mão com as palmas viradas para o corpo', 'Com os braços parados, expire e flexione os pesos contraindo os bíceps, continuando a subir até que os bíceps estejam contraídos e os halteres na altura dos ombros', 'Ajuste os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Flexione o peso com as palmas viradas para baixo, mantendo os cotovelos próximos e o tronco parado', 'Mantenha o tronco imóvel e use a flexão do cotovelo para levantar o peso', 'Abaixe até que os cotovelos estejam quase estendidos, mantendo a parte superior dos braços parada']),
  ('0jp9Rlz', 'Eleva&ccedil&atilde;o de panturrilha unilateral no solo', array['Fique de p&eacute; com os p&eacute;s na largura dos quadris e apoie as m&atilde;os em uma parede ou objeto firme para ter equil&iacute;brio', 'Antes de se mover, tire um p&eacute; do ch&atilde;o e equilibre-se sobre o outro p&eacute;', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece est&aacutevel', 'Suba apoiando-se na ponta dos p&eacute;s, elevando os calcanhares o mais alto poss&ivel sem balan&7ar', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o esfor&ccedil;o', 'Abaixe os calcanhares em ritmo controlado antes de subir novamente; troque de lado quando a s&eacute;rie exigir']),
  ('0JtKWum', 'Burpee com halter', array['Comece em posi&ccedil&atilde;o em p&eacute; com os p&eacute;s na largura dos ombros e um halter em cada m&atilde;o', 'Antes de se mover, abaixe o corpo em posi&ccedil&atilde;o de agachamento, colocando os halter no ch&atilde;o &agrave; sua frente', 'Come&7e em um ritmo que permita que p&eacute;s e bra&ccedil;os se movam em sincronia', 'Mova-se em um ritmo repet&ivel, mantendo o movimento fluido e a respira&ccedil&atilde;o constante', 'Mantenha o padr&atilde;o repet&ivel conforme a velocidade aumenta', 'Mantenha o ritmo pelo intervalo planejado, diminuindo a velocidade se a t&eacutenica começar a falhar']),
  ('0L2KwtI', 'Alongamento de quadril e lat&eacutessimo com rolo', array['Come&7e ajoelhado no ch&atilde;o com o rolo posicionado sob os quadris', 'Apoie as m&atilde;os no rolo para dar suporte', 'Acomode-se na posi&ccedil&atilde;o inicial e respire calmamente antes de aprofundar o movimento', 'Aproxime-se do alongamento at&eacutete sentir uma tens&atilde;o leve; continue respirando e evite dar trancos', 'Permane&eactee em um alongamento leve em vez de puxar mais com impulso', 'Mantenha a posi&atilde;o com respira&ccedil&atilde;o constante e solte suavemente; repita do outro lado se necess&eacuterio']),
  ('0lQnxMZ', 'Agachamento sissy com peso', array['Fique de p&eacute; com os p&eacute;s na largura dos ombros e as pontas dos p&eacute;s apontando levemente para fora', 'Segure um peso &agrave; frente do peito com ambas as m&atilde;os ou coloque uma barra sobre a parte superior das costas', 'Contraia o abd&ocircmen e distribua a press&atilde;o por todo o p&eacute;', 'Flexione os quadris e joelhos para descer, mantendo os p&eacute;s apoiados e os joelhos alinhados com os dedos dos p&eacute;s', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos caiam para dentro', 'Fique totalmente em p&eacute;, ajuste a base e a respira&ccedil&atilde;o, ent&atilde;o come&7e a pr&oacutetica descida']),
  ('0mB6wHO', 'Alongamento do corredor', array['Fique de p&eacute; com os p&eacute;s na largura dos quadris', 'D&ecirc um passo &agrave; frente com o p&eacute; direito, mantendo o p&eacute; esquerdo apoiado', 'Acomode-se na posi&ccedil&atilde;o inicial e respire calmamente antes de aprofundar o movimento', 'Aproxime-se do alongamento at&eacutete sentir uma tens&atilde;o leve; continue respirando e evite dar trancos', 'Permane&eactee em um alongamento leve em vez de puxar mais com impulso', 'Mantenha a posi&atilde;o com respira&ccedil&atilde;o constante e solte suavemente; repita do outro lado se necess&eacuterio']),
  ('0MlxeMn', 'Puxada frontal com barra reta', array['Ajuste a altura do assento para que suas coxas fiquem paralelas ao ch&atilde;o e seus p&eacute;s apoiados no ch&atilde;o', 'Segure a barra com as palmas das m&atilde;os viradas para baixo, logo acima da largura dos ombros', 'Sente-se erguido e alinhe os ombros antes de puxar a barra para baixo', 'Puxe a barra para baixo direcionando os cotovelos em dire&ccedil&atilde;o &agrave;s costelas; mantenha o tronco est&aacutevel', 'Puxe com os cotovelos em vez de se inclinar muito para tr&eacutete para mover a barra', 'Deixe a barra subir de forma controlada at&eacutete que os bra&ccedil;os estejam esticados, ent&atilde;o reorganize os ombros']),
  ('0rHfvy9', 'Flex&atilde;o de perna inversa (na m&aacutequina de cabo para barra fixa)', array['Ajuste a m&aacutequina de cabo para que as tiras de tornozelo fiquem na regulagem mais baixa', 'Posicione-se de barriga para baixo no banco com as pernas estendidas e as tiras de tornozelo presas aos p&eacute;s', 'Alinhe os joelhos com a borda da m&aacutequina ou do banco antes de come&7ar a flex&atilde;o', 'Flexione os joelhos para puxar o apoio em sua dire&ccedil&atilde;o sem levantar os quadris do suporte', 'Mantenha os quadris parados enquanto os joelhos se flexionam', 'Retorne devagar &agrave; posi&ccedil&atilde;o inicial antes de repetir']),
  ('0S75mYG', 'Eleva&ccedil&atilde;o de panturrilha unilateral sentada no Smith', array['Sente-se na m&aacutequina com as costas apoiadas no encosto e os p&eacute;s no suporte', 'Apoie uma perna no suporte e mantenha a outra perna fora dele', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece est&aacutevel', 'Suba apoiando-se na ponta dos p&eacute;s, elevando os calcanhares o mais alto poss&ivel sem balan&7ar', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o esfor&ccedil;o', 'Abaixe os calcanhares em ritmo controlado antes de subir novamente; troque de lado quando a s&eacute;rie exigir']),
  ('0V2YQjW', 'Barra fixa (pegada neutra)', array['Suspenso em uma barra com pegada neutra e braços estendidos', 'Contraia o tronco e aproxime as escápulas', 'Inicie a partir de uma suspensão controlada com os ombros ativos', 'Puxe os cotovelos para baixo e aproxime a parte superior do peito da barra', 'Evite balançar as pernas para ultrapassar a barra', 'Desça com os braços estendidos sem soltar de uma vez']),
  ('0xDpB4L', 'Abdução de quadril sentada com elástico', array['Sente-se em uma cadeira ou banco com as costas retas e pés apoiados', 'Posicione a faixa de resistência ao redor das coxas, logo acima dos joelhos', 'Alinhe a pelve antes de mover a perna de trabalho', 'Abra os joelhos contra a resistência sem mover o tronco', 'Controle a faixa na volta em vez de deixar puxar rapidamente', 'Retorne pelo mesmo caminho em ritmo controlado']),
  ('0Yz8WdV', 'Caminhada de urso', array['Apoie as mãos e os joelhos no chão, com mãos sob os ombros e joelhos sob os quadris', 'Antes de mover, levante os joelhos levemente do chão, mantendo as costas retas e o core contraído', 'Comece em um ritmo que permita mover pés e braços em sincronia', 'Mova-se em um ritmo constante, mantendo o movimento suave e a respiração firme', 'Mantenha o padrão repetível conforme a velocidade aumenta', 'Mantenha o ritmo pelo tempo planejado, diminuindo se a forma falhar']),
  ('10Z2DXU', 'Leg press 45° na máquina', array['Ajuste o assento e a plataforma da máquina em uma posição confortável', 'Sente-se com as costas no encosto e os pés na largura dos ombros na plataforma', 'Apoie firmemente os pés na placa e mantenha o quadril no assento', 'Flexione os joelhos para trazer a plataforma na sua direção e empurre para longe com os pés', 'Interrompa a descida antes que o quadril levante do assento', 'Retorne o peso ou corpo à posição inicial sem pressa']),
  ('11wrviz', 'Limpadores isométricos', array['Deite-se de costas em um colchonete ou banco', 'Estique os braços para os lados, perpendiculares ao corpo', 'Fixe a pelve e faça o giro pela caixa torácica', 'Mantenha o tronco contraído enquanto as pernas se movem juntas de um lado para o outro', 'Mantenha o giro suave em vez de jogar os braços sobre o corpo', 'Retorne pelo centro antes de girar para o outro lado']),
  ('13TpY4H', 'Flexão com um braço elevado', array['Inicie em posição de flexão com as mãos um pouco além da largura dos ombros e pés juntos', 'Estenda um braço para o lado, paralelo ao chão', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito mantendo o corpo alinhado', 'Mantenha a cabeça alinhada à coluna enquanto flexiona os cotovelos', 'Empurre de volta à extensão dos braços, mantendo o corpo alinhado']),
  ('13VW2VO', 'Afundo com alongamento e peso', array['Fique em pé com os pés na largura dos ombros', 'Dê um passo à frente com o pé direito, mantendo a coluna firme', 'Ajuste a posição inicial e respire calmamente antes de aprofundar', 'Aproxime-se do alongamento até sentir leve tensão, mantendo a respiração e sem balançar', 'Mantenha um alongamento leve em vez de puxar com impulso', 'Segure a posição respirando firmemente e libere devagar, repetindo do outro lado se necessário']),
  ('17bqEXD', 'Alongamento de panturrilha sentado', array['Sente-se na borda de uma cadeira ou banco com os pés apoiados', 'Estique uma perna à frente com o calcanhar no chão', 'Ajuste a posição inicial e respire calmamente antes de aprofundar', 'Abaixe o calcanhar e ajuste até esticar a panturrilha, mantendo o pé apontado para frente', 'Mantenha um alongamento leve em vez de puxar com impulso', 'Segure a posição respirando firmemente e libere devagar, repetindo do outro lado se necessário']),
  ('17lJ1kr', 'Flexão de joelhos deitado na máquina', array['Ajuste a máquina ao seu corpo e selecione o peso desejado', 'Posicione-se de bruços na máquina com as pernas esticadas e os calcanhares contra a alavanca almofadada', 'Alinhe os joelhos com a borda da máquina ou do banco antes de iniciar a flexão', 'Flexione os joelhos para puxar a almofada em sua direção sem levantar os quadris do apoio', 'Mantenha os quadris parados enquanto os joelhos se flexionam', 'Retorne suavemente ao início antes de repetir']),
  ('196HJGw', 'Elevação pélvica (joelho flexionado)', array['Deite-se de costas com os joelhos flexionados e os pés apoiados no chão', 'Posicione as mãos ao lado do corpo com as palmas viradas para baixo', 'Apoie os pés e evite arquear as costelas enquanto os quadris se preparem para subir', 'Empurre pelos pés e levante os quadris até que o tronco e as coxas fiquem alinhados', 'Pare quando os quadris se alinharem com o tronco; não arqueie mais a parte inferior das costas', 'Abaixe os quadris de forma constante e mantenha os pés apoiados para a próxima elevação']),
  ('1bQkKZK', 'Good morning com joelhos flexionados noSmith', array['Fique em pé com os pés na largura dos ombros e os dedos apontados para a frente', 'Posicione a barra na parte superior das costas, apoiada nos trapézios', 'Destrave os joelhos e contraia o abdômen antes de mover os quadris para trás', 'Empurre os quadris para trás mantendo a carga próxima e a coluna firme', 'Mantenha o peso próximo às pernas e pare quando as costas começarem a arredondar', 'Empurre os quadris para a frente para ficar totalmente em pé sem inclinar para trás no topo']),
  ('1cTf2Ux', 'Rosca francesa em pé com barra EZ', array['Fique em pé com os pés na largura dos ombros e segure a barra EZ com as palmas viradas para baixo', 'Eleve a barra acima da cabeça esticando os braços', 'Posicione os braços no lugar antes de estender os cotovelos', 'Flexione os cotovelos para abaixar a barra atrás da cabeça enquanto os braços permanecem praticamente parados', 'Mantenha os braços firmes enquanto os antebraços se movimentam', 'Estique os cotovelos para trazer a barra acima da cabeça e inicie a próxima repetição controlada']),
  ('1DN3iz4', 'Remada alta no Smith', array['Fique em pé com os pés na largura dos ombros, de frente para a máquina Smith', 'Segure a barra com as palmas viradas para baixo e as mãos logo acima da largura dos ombros', 'Posicione o tronco e permita que os braços alcancem a frente sem arredondar excessivamente', 'Puxe os cotovelos para trás e traga a barra ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços para a frente novamente sem deixar o tronco balançar']),
  ('1g5bPpA', 'Polichinelo', array['Fique em pé com os pés juntos e os braços ao lado do corpo', 'Antes de se mover, dê um salto afastando os pés e elevando os braços acima da cabeça', 'Flexione levemente os quadris e os joelhos para preparar o salto', 'Carregue as pernas com uma pequena flexão, impulsione pelo chão e aterrisse suavemente', 'Aterrisse com quadris e joelhos flexionados e deixe os pés absorverem o impacto', 'Absorva a aterrissagem através dos quadris e joelhos antes de repetir']),
  ('1gFNTZV', 'Agachamento com salto com barra', array['Comece em pé com os pés na largura dos ombros, segurando uma barra na parte superior das costas', 'Antes de se mover, abaixe o corpo em posição de agachamento flexionando os joelhos e empurrando os quadris para trás', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e joelhos para descer, mantendo os pés firmes e os joelhos alinhados com os dedos dos pés', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos desabem para dentro', 'Fique totalmente em pé, ajuste sua base e respiração e inicie a próxima descida']),
  ('1GPHRyK', 'Abdominal Janda', array['Deite-se de costas com os joelhos flexionados e os pés apoiados no chão', 'Posicione as mãos atrás da cabeça com os cotovelos apontados para fora', 'Posicione a pelve e mantenha o pescoço relaxado antes de flexionar o tronco para cima', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento focado no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão']),
  ('1IFV9h3', 'Flexão com apoio nos antebraços', array['Inicie em uma posição de prancha com os antebraços no chão e os cotovelos diretamente abaixo dos ombros.', 'Contraia o tronco e mantenha o corpo em linha reta da cabeça aos pés.', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos.', 'Flexione os cotovelos para abaixar o peito enquanto mantém o corpo em linha reta.', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos se flexionam.', 'Empurre de volta para os braços esticados, mantendo a linha do corpo intacta.']),
  ('1IG6gVF', 'Rotação de tronco em decúbito ventral na bola suíça', array['Comece deitado de bruços em uma bola suíça com os pés na largura dos ombros e os dedos tocando o chão.', 'Posicione as mãos atrás da cabeça ou cruze-as sobre o peito.', 'Estabilize a pelve e faça a rotação através da caixa torácica.', 'Gire o tronco enquanto os quadris e a parte inferior do corpo permanecem o mais firmes possível.', 'Mantenha a bola estável e use os pés para controlar o seu equilíbrio.', 'Retorne ao centro antes de girar para o outro lado.']),
  ('1jXLYEw', 'Alongamento lateral em pé', array['Fique em pé com os pés na largura dos ombros e os joelhos levemente flexionados.', 'Estenda os braços para os lados, paralelos ao chão.', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento.', 'Vá em direção ao alongamento até sentir uma tensão leve; continue respirando e evite balançar.', 'Permaneça em um alongamento leve em vez de puxar mais com impulso.', 'Mantenha a posição com respiração constante, depois solte suavemente; repita do outro lado, se necessário.']),
  ('1kB3Wmk', 'Elevação de calcanhar unilateral com halter', array['Suba na borda de um degrau ou plataforma com os calcanhares para fora e a ponta dos pés apoiada.', 'Pegue um halter em uma mão e coloque a outra mão em uma parede ou corrimão para apoio.', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel.', 'Suba na ponta dos pés, levantando os calcanhares o mais alto possível sem balançar.', 'Faça uma pausa no topo sem girar os tornozelos para fora.', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente.']),
  ('1LVFcEn', 'Alongamento de panturrilha com corda', array['Fique de frente para uma parede ou objeto firme com os pés na largura dos quadris.', 'Segure as pontas da corda em cada mão e coloque o meio da corda ao redor da ponta do pé direito.', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento.', 'Abaixe o calcanhar e desloque o corpo até a panturrilha esticar; mantenha o pé apontado para a frente.', 'Permaneça em um alongamento leve em vez de puxar mais com impulso.', 'Mantenha a posição com respiração constante, depois solte suavemente; repita do outro lado, se necessário.']),
  ('1oE78pm', 'Remada alta com barra', array['Fique em pé com os pés na largura dos ombros e segure uma barra com as palmas para baixo, mãos logo além da largura dos ombros.', 'Mantenha a barra pendurada à frente das coxas, com os braços esticados.', 'Posicione o tronco e permita que os braços alcancem a frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e traga a barra ou o peso em direção ao tronco.', 'Traga os cotovelos para trás sem dar trancos no tronco.', 'Estenda os braços para a frente novamente sem deixar o tronco balançar.']),
  ('1PK5Uo3', 'Tríceps pulley inclinado na polia', array['Conecte uma barra reta a uma máquina de polia alta.', 'Fique de costas para a máquina com uma base estável e os pés na largura dos ombros.', 'Fique a uma distância suficiente da pilha de pesos para que o cabo permaneça tenso.', 'Mantenha os cotovelos próximos às costelas e estenda os braços contra o cabo.', 'Mantenha os cotovelos próximos ao corpo em vez de deixar os ombros balançarem.', 'Retorne pelo mesmo caminho em um ritmo controlado.']),
  ('1PLE8e9', 'Crucifixo inclinado com halteres e rotação', array['Ajuste um banco inclinado a 45 graus e sente-se nele com um halter em cada mão, com as palmas viradas uma para a outra.', 'Deite-se no banco e empurre os halteres para a posição inicial, diretamente acima do peito, com os braços estendidos.', 'Mantenha uma leve flexão nos cotovelos e estabilize os ombros antes de mover os braços.', 'Com uma leve flexão nos cotovelos, junte os braços em um arco amplo.', 'Mantenha o ângulo do cotovelo praticamente inalterado durante todo o arco.', 'Abra os braços de volta pelo mesmo arco sem abaixar a carga.']),
  ('1YB40kg', 'Flexão inclinada com pegada fechada', array['Posicione as mãos juntas em uma superfície elevada e estável, depois afaste os pés para trás em posição de prancha.', 'Estenda as pernas para trás, apoiando-se na ponta dos pés, com o corpo formando uma linha reta da cabeça aos calcanhares.', 'Contraia o abdômeno e os glúteos para que ombros, quadris e tornozelos se movam juntos.', 'Flexione os cotovelos para abaixar o peito, mantendo o corpo alinhado.', 'Mantenha a cabeça alinhada com a coluna enquanto flexiona os cotovelos.', 'Empurre para cima até esticar os braços, mantendo o alinhamento do corpo.']),
  ('1YUWDNZ', 'Remada invertida', array['Ajuste uma barra na altura da cintura ou use um aparelho de suspensão.', 'Fique de frente para a barra ou para o aparelho de suspensão, com os pés na largura dos ombros.', 'Posicione o tronco e deixe os braços esticados para frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e traga a pegada ou o peso em direção ao tronco.', 'Traga os cotovelos para trás sem dar trancos no tronco.', 'Estenda os braços para frente novamente sem deixar o tronco balançar.']),
  ('1ZFqTDN', 'Abdominal bicicleta', array['Deite-se de costas com as mãos posicionadas atrás da cabeça.', 'Antes de se mover, tire os pés do chão e flexione os joelhos em um ângulo de 90 graus.', 'Ajuste a pelve e mantenha o pescoço relaxado antes de subir o tronco.', 'Traga um cotovelo em direção ao joelho oposto enquanto a outra perna se estende; alterne os lados em um ritmo constante.', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento focado no tronco.', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão.']),
  ('225x2Vd', 'Abdominal com rotação no colchonete com elástico', array['Prenda o elástico em um ponto de ancoragem firme na altura da cintura.', 'Ajoelhe-se de costas para o ponto de ancoragem e segure o elástico com as duas mãos, mantendo os cotovelos flexionados e próximos ao corpo.', 'Ajuste a pelve e mantenha o pescoço relaxado antes de subir o tronco.', 'Curve a caixa torácica em direção à pelve, deixando o abdômen mover o tronco.', 'Controle o elástico na volta em vez de deixar que ele puxe você de uma vez.', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão.']),
  ('25GPyDY', 'Rosca direta com barra', array['Fique em pé com os pés na largura dos ombros e segure uma barra com as palmas das mãos viradas para cima e para frente.', 'Mantenha os cotovelos próximos ao tronco, expire e flexione o peso enquanto contrai os bíceps.', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos.', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco.', 'Mantenha o tronco firme e use a flexão dos cotovelos para levantar o peso.', 'Abaixe até que os braços estejam quase esticados, mantendo a parte superior dos braços parada.']),
  ('27NNGFr', 'Crucifixo inclinado no cabo (na bola suíça)', array['Posicione uma bola suíça em um ângulo inclinado.', 'Conecte os puxadores do cabo às polias altas de uma máquina de cabo.', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços.', 'Com uma leve flexão nos cotovelos, junte os braços em um arco amplo.', 'Mantenha a bola firme e use os pés para controlar seu equilíbrio.', 'Abra os braços de volta pelo mesmo arco sem deixar o peso cair.']),
  ('2dImyQ8', 'Rosca de punho sentada com halteres com as palmas para cima', array['Apoie bem os dois pés enquanto estiver sentado em um banco; segure um halter em cada mão com as palmas viradas para cima.', 'Apoie os antebraços nas coxas, deixando os punhos para fora da borda.', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço suportem a carga.', 'Movimente os punhos ou dedos enquanto os antebraços permanecem apoiados e parados.', 'Use uma amplitude pequena e suave sem balançar os cotovelos.', 'Retorne à posição inicial com controle, sem deixar o peso escapar das mãos.']),
  ('2Dk4xQV', 'Alongamento de sapo com balanço', array['Comece ajoelhado no chão com os joelhos na largura dos quadris.', 'Apoie as mãos no chão à sua frente para ter estabilidade.', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento.', 'Aproxime-se do alongamento até sentir uma tensão leve; continue respirando e evite dar trancos.', 'Mantenha-se em um alongamento leve em vez de puxar mais com impulso.', 'Mantenha a posição respirando calmamente, depois solte devagar; repita do outro lado se necessário.']),
  ('2kr2lWy', 'Flexão com bola bosu', array['Posicione a bola bosu no chão com o lado plano voltado para cima', 'Coloque-se em posição de flexão com as mãos nas bordas externas da bola bosu', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Dobre os cotovelos para abaixar o peito, mantendo o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos dobram', 'Empurre de volta para cima com os braços esticados, mantendo a linha do corpo intacta']),
  ('2LQkNPW', 'Alongamento de flexor do quadril na bola suíça', array['Posicione a bola suíça no chão e ajoelhe-se na frente dela', 'Coloque o pé direito em cima da bola suíça com o joelho dobrado em um ângulo de 90 graus', 'Ajuste-se na posição inicial e respire calmamente antes de aprofundar o movimento', 'Aproxime-se do alongamento até sentir uma tensão leve; continue respirando e evite balançar', 'Mantenha a bola firme e use os pés para controlar o seu equilíbrio', 'Segure a posição com respiração constante, depois solte suavemente; repita do outro lado se necessário']),
  ('2NImIAG', 'Rosca biscoito com halteres na bola suíça com perna elevada', array['Sente-se em uma bola suíça com os pés apoiados e as costas retas', 'Segure um halter em cada mão com as palmas voltadas para a frente e os braços esticados', 'Posicione os ombros e a parte superior dos braços antes de dobrar os cotovelos', 'Dobre os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha a bola firme e use os pés para controlar o seu equilíbrio', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços parada']),
  ('2NpxjC1', 'Rosca martelo com halteres', array['Fique em pé com um halter em cada mão, com as palmas voltadas para o tronco', 'Mantenha os cotovelos perto do tronco e gire as palmas das mãos até que estejam voltadas para a frente', 'Posicione os ombros e a parte superior dos braços antes de dobrar os cotovelos', 'Faça a rosca com as palmas voltadas uma para a outra e os cotovelos próximos aos lados; evite inclinar para trás', 'Mantenha as palmas voltadas uma para a outra e os pulsos retos', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços parada']),
  ('2ORFMoR', 'Elevação de panturrilha no hack', array['Ajuste a máquina com um peso confortável', 'Suba na máquina com os dedos dos pés na plataforma e os calcanhares para fora', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel', 'Suba na ponta dos pés, levantando os calcanhares o mais alto possível sem balançar', 'Faça uma pausa no topo sem girar os tornozelos para fora', 'Abaixe os calcanhares em ritmo controlado antes de subir novamente']),
  ('2Pya1cP', 'Supino declinado no cabo', array['Ajuste a máquina de cabos em uma posição declinada', 'Sente-se no banco declinado de frente para a máquina de cabos', 'Contraia o tronco e alinhe os pulsos com os antebraços', 'Empurre o peso ou as alças para longe, mantendo o tronco contraído', 'Mantenha os pulsos alinhados e use um caminho para os ombros que pareça natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('2Qh2J1e', 'Leg press 45°', array['Ajuste o assento da máquina para que seus joelhos fiquem em um ângulo de 90 graus quando seus pés estiverem na plataforma', 'Sente-se na máquina com as costas apoiadas no encosto e os pés na largura dos ombros na plataforma', 'Apoie os pés firmemente na plataforma e mantenha os quadris contra o assento', 'Dobre os joelhos para trazer a plataforma em sua direção e, em seguida, empurre-a para longe com os pés', 'Interrompa a descida antes que os quadris se levantem do assento', 'Traga o peso ou o corpo de volta à posição inicial sem pressa']),
  ('2qTvJAZ', 'Rosca de punho invertida em pé com barra', array['Fique em pé com os pés na largura dos ombros e segure uma barra com as palmas voltadas para baixo', 'Apoie a barra nas costas das mãos com as palmas voltadas para baixo e os dedos apontando para o corpo', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço suportem a carga', 'Mova-se pelos punhos ou dedos enquanto os antebraços permanecem apoiados e parados', 'Use uma amplitude pequena e suave sem balançar os cotovelos', 'Volte suavemente ao início sem deixar a carga cair das suas mãos']),
  ('3omWx6P', 'Rosca bicep alternada com elastico', array['Fique de pe com os pes na largura dos ombros e segure o elastico com as palmas voltadas para cima.', 'Mantenha os cotovelos proximos aos flancos e, com controle, flexione um braco em direcao ao ombro, contraindo o bicep no topo.', 'Posicione os ombros e os bracos antes de flexionar os cotovelos.', 'Flexione os cotovelos para trazer o peso em direcao aos ombros sem balancar o tronco.', 'Conclua o movimento de um lado antes que o outro lado assuma o controle.', 'Abaixe ate que os cotovelos estejam quase retos, mantendo os bracos imoveis; alterne os lados quando necessario.']),
  ('3pqGMQj', 'Abdominal em V alternado com elastico', array['Deite-se de costas com as pernas esticadas e os bracos estendidos para cima, segurando o elastico.', 'Contraia oabdomen e levante as pernas e a parte superior do corpo do solo simultaneamente, alcancando as maos em direcao aos pes.', 'Posicione a pelve e mantenha o pescoco relaxado antes de subir.', 'Eleve as pernas retas e o tronco juntos, alcancando os pes antes de abaixar com controle.', 'Conclua o movimento de um lado antes que o outro lado assuma o controle.', 'Abaixe os ombros ou o tronco com controle antes da proxima elevacao; alterne os lados quando necessario.']),
  ('3QgteDK', 'Supino reto com pegada inversa e barra larga', array['Sente-se em um banco com os pes apoiados e as costas pressionadas contra o banco.', 'Segure a barra com uma pegada inversa larga, logo acima da largura dos ombros.', 'Contraia o tronco e alinhe os pulsos com os antebracos.', 'Pressione o peso para longe enquanto mantem o tronco contraido.', 'Mantenha as palmas na pegada escolhida sem curvar os pulsos para tras.', 'Abaixe o peso ate a altura inicial com controle antes de pressionar novamente.']),
  ('3s4NnTh', 'Rosca direta em pe com halteres', array['Fique erguido com um halter em cada mao, palmas voltadas para a frente e bracos retos.', 'Com os bracos imoveis, expire e flexione os pesos enquanto contrai os biceps.', 'Posicione os ombros e os bracos antes de flexionar os cotovelos.', 'Flexione os cotovelos para trazer o peso em direcao aos ombros sem balancar o tronco.', 'Mantenha o tronco parado e deixe a flexao do cotovelo erguer o peso.', 'Abaixe ate que os cotovelos estejam quase retos, mantendo os bracos imoveis.']),
  ('3T12T87', 'Extensao de triceps com dois halteres curvado em pe', array['Fique de pe com os pes na largura dos ombros e segure um halter em cada mao.', 'Incline-se para a frente na cintura, com a coluna firme e os joelhos flexionados.', 'Posicione os bracos no lugar antes de estender os cotovelos.', 'Mantenha os bracos estaveis e estenda pelos cotovelos para mover o peso.', 'Mantenha os bracos estaveis enquanto os antebracos se movimentam.', 'Flexione os cotovelos lentamente para retornar ao inicio da proxima repeticao.']),
  ('3tAXPQ6', 'Rosca inversa de punho com halteres no banco', array['Apoie ambos os pes enquanto esta sentado em um banco; segure um halter em cada mao, palmas voltadas para baixo.', 'Apoie os antebracos no banco, deixando os pulsos livres alem da borda.', 'Mantenha os cotovelos relaxados para que os pequenos musculos da mao ou antebraco suportem a carga.', 'Mova-se pelos pulsos ou dedos enquanto os antebracos permanecem apoiados e imoveis.', 'Use uma amplitude pequena e suave sem balancar os cotovelos.', 'Volte ao inicio sem deixar a carga cair de suas maos.']),
  ('3TZduzM', 'Supino inclinado com barra', array['Ajuste o banco para aproximadamente 45 graus.', 'Deite-se no banco com os pes apoiados.', 'Contraia o tronco e alinhe os pulsos com os antebracos.', 'Pressione o peso para longe enquanto mantem o tronco contraido.', 'Mantenha os pulsos alinhados e use uma trajetoria de ombro que pareca natural.', 'Abaixe o peso ate a altura inicial com controle antes de pressionar novamente.']),
  ('3uj0Ozg', 'Alongamento dinamico de peito', array['Fique erguido e ajuste os pes na largura dos ombros.', 'Estenda os bracos para as laterais, paralelos ao solo.', 'Posicione-se na posicao inicial e respire fundo antes de aprofundar o movimento.', 'Avance em direcao ao alongamento ate sentir uma tensao leve; continue respirando e evite balancar.', 'Mantenha um alongamento leve em vez de puxar com impulso.', 'Segure a posicao com respiracao constante e solte suavemente; repita do outro lado, se necessario.']),
  ('3XFdb1Z', 'Rosca com agachamento no cabo', array['Conecte um puxador na regulagem mais baixa de uma máquina de cabo', 'Fique de frente para a máquina em uma base estável com os pés na largura dos ombros', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos', 'Empurre para cima com o peito e quadris subindo juntos; evite que os joelhos fechem para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a próxima descida']),
  ('3xK09Sk', 'Remada com agachamento com peso corporal', array['Fique em pé com os pés na largura dos ombros, segurando em um objeto firme ou fita de suspensão com os braços estendidos', 'Desça o corpo em uma posição de agachamento, com a coluna firme e os joelhos atrás dos dedos dos pés', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos', 'Empurre para cima com o peito e quadris subindo juntos; evite que os joelhos fechem para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a próxima descida']),
  ('3ZflifB', 'Tríceps no cabo', array['Conecte uma barra reta a uma máquina de cabo com polia alta', 'Fique de frente para a máquina com os pés na largura dos ombros e uma leve flexão nos joelhos', 'Fique a uma distância suficiente para que o cabo fique tenso', 'Mantenha os cotovelos próximos às costelas e estenda os braços contra o cabo', 'Mantenha os cotovelos perto do corpo em vez de deixar os ombros balançarem', 'Retorne suavemente ao início antes de repetir']),
  ('4c9BhzB', 'Puxada frontal no cabo com barra V', array['Sente-se na máquina de puxada e segure o puxador em V com as palmas voltadas para baixo', 'Ajuste o apoio de joelhos para que suas coxas fiquem firmes sob ele', 'Sente-se erguido e ajuste os ombros antes de puxar a barra para baixo', 'Puxe o puxador para baixo direcionando os cotovelos para as costelas; mantenha o tronco firme', 'Puxe com os cotovelos em vez de se inclinar muito para trás para mover o puxador', 'Deixe o puxador subir de forma controlada até os braços estarem estendidos, depois ajuste os ombros']),
  ('4CBIBOM', 'Extensão de tríceps com barra sentado atrás do pescoço', array['Sente-se em um banco com a coluna reta e os pés apoiados', 'Segure a barra com uma pegada fechada atrás do pescoço, com as palmas voltadas para a frente', 'Posicione os braços firmes antes de estender os cotovelos', 'Mantenha a parte superior dos braços firme e estenda através dos cotovelos para mover o peso', 'Mantenha os braços firmes enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('4cWjYEN', 'Flexão fechada na bola suíça', array['Coloque a bola suíça no chão e assuma a posição de flexão com as mãos na bola, um pouco mais fechadas que a largura dos ombros', 'Contraia o tronco e mantenha o corpo em linha reta da cabeça aos pés', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito enquanto mantém o corpo alinhado', 'Mantenha a bola firme e use os pés para controlar o equilíbrio', 'Empurre de volta para os braços estendidos, mantendo o alinhamento corporal intacto']),
  ('4dF3maG', 'Rosca scott unilateral com halteres e pegada neutra', array['Sente-se em um banco scott com um halter em uma das mãos e o braço apoiado no suporte', 'Segure o halter com pegada neutra (palmas voltadas para o corpo)', 'Apoie o braço em trabalho no banco scott deixando o cotovelo livre para flexionar', 'Faça a rosca com o peso mantendo a parte superior do braço em contato com o suporte', 'Mantenha ambos os ombros nivelados e evite virar o corpo em direção ao braço em movimento', 'Desça até que os braços estejam quase estendidos, mantendo a parte superior do braço imóvel; alterne os lados quando necessário']),
  ('4dUn2iv', 'Rosca direta com barra em pé e pegada fechada', array['Fique em pé com os pés na largura dos ombros e segure uma barra com as palmas voltadas para cima, mãos próximas', 'Mantenha os cotovelos próximos ao tronco e os braços imóveis durante todo o movimento', 'Ajuste os ombros e os braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco firme e deixe a flexão do cotovelo levantar o peso', 'Desça até que os cotovelos estejam quase estendidos, mantendo a parte superior dos braços imóvel']),
  ('4f8RXP8', 'Remada baixa com cabo (barra V)', array['Fique de frente para a polia com uma base estável e pés na largura dos ombros', 'Segure o acessório de barra V com as palmas das mãos voltadas para baixo', 'Posicione o tronco e estenda os braços à frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a manopla ou o peso em direção ao tronco', 'Recue os cotovelos sem dar trancos com o tronco', 'Estenda os braços à frente novamente sem deixar o tronco balançar']),
  ('4GqRrAk', 'Flexão superman', array['Comece em posição de prancha alta com as mãos um pouco além da largura dos ombros e os pés juntos', 'Contraia o tronco e abaixe o corpo em direção ao chão, mantendo os cotovelos próximos às costelas', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito enquanto mantém o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre de volta até esticar os braços, mantendo a linha do corpo intacta']),
  ('4H86mXM', 'Leg Press 45 Graus Unilateral', array['Ajuste a máquina de leg press a um ângulo de 45 graus', 'Sente-se no aparelho com as costas apoiadas no encosto e os pés na plataforma', 'Apoie os pés firmemente na plataforma e mantenha o quadril contra o assento', 'Flexione os joelhos para trazer a plataforma na sua direção e empurre para longe com os pés', 'Mantenha a pelve nivelada enquanto a perna de apoio realiza o trabalho', 'Retorne suavemente ao início antes de repetir; alterne os lados quando necessário']),
  ('4hATdoB', 'Rosca Scott com cabo e corda unilateral', array['Conecte um puxador de corda a uma polia baixa', 'Fique de frente para a máquina com uma base estável e pés na largura dos ombros', 'Apoie o braço de trabalho no apoio do banco Scott e deixe o cotovelo livre para flexionar', 'Flexione o peso enquanto o braço permanece em contato com o apoio', 'Mantenha ambos os ombros nivelados e evite girar o corpo para o lado do braço em movimento', 'Abaixe até que o cotovelo esteja quase reto mantendo o braço parado; alterne os lados quando necessário']),
  ('4ievMJ9', 'Tríceps testa sentado com halteres', array['Apoie ambos os pés no chão sentado em um banco e segure um halter em cada mão', 'Incline o tronco para a frente na cintura com a coluna firme e a cabeça erguida', 'Posicione os braços antes de estender os cotovelos', 'Mantenha os braços firmes e estenda os cotovelos para mover o peso', 'Mantenha os braços parados enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('4IKbhHV', 'Puxada frontal alternada', array['Sente-se na polia com as costas retas e os pés apoiados', 'Segure as manoplas com as palmas voltadas para baixo logo acima da largura dos ombros', 'Sente-se erguido e posicione os ombros antes de puxar a manopla para baixo', 'Puxe a manopla direcionando os cotovelos para as costelas e mantenha o tronco firme', 'Conclua o movimento de um lado antes que o outro lado inicie', 'Deixe a manopla subir de forma controlada até os braços estarem esticados, reinicie os ombros e alterne os lados']),
  ('4Jc36XM', 'Rosca de punho reversa unilateral com halter sobre o banco', array['Apoie ambos os pés sentado em um banco, segure um halter em uma mão com a palma voltada para baixo', 'Apoie o antebraço no banco com o punho para fora da borda', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou antebraço suportem a carga', 'Movimente através dos punhos ou dedos enquanto os antebraços permanecem apoiados e imóveis', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço de trabalho', 'Retorne suavemente ao início sem deixar a carga escapar das mãos; alterne os lados quando necessário']),
  ('4Jt8QsQ', 'Flexão sobre os antebraços', array['Comece em posição de prancha com os antebraços no chão e cotovelos diretamente abaixo dos ombros', 'Contraia o tronco e mantenha o corpo em linha reta da cabeça aos pés', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito enquanto mantém o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre de volta até esticar os braços, mantendo a linha do corpo intacta']),
  ('4KJEpzb', 'Remada alta invertida com kettlebell a partir da posição suspensa', array['Fique em pé com os pés na largura dos ombros, segurando um kettlebell em uma mão com a palma para baixo', 'Flexione levemente os joelhos e incline o tronco à frente pelo quadril, mantendo a coluna firme e o peito estufado', 'Contraia o abdômen antes de puxar e mantenha a carga próxima ao corpo', 'Impulsione pelas pernas e quadris, depois guie o peso para a posição de recepção', 'Receba a carga com o tronco firme e os pés estáveis', 'Fique em pé para finalizar, depois desça o peso de forma controlada antes da próxima repetição']),
  ('4Leypho', 'Remada alta com barra estilo esquiador', array['Fique em pé com os pés na largura dos ombros e segure uma barra à frente das coxas com as palmas para baixo', 'Flexione levemente os joelhos e incline o tronco à frente pelo quadril, mantendo a coluna firme e o peito estufado', 'Contraia o abdômen antes de puxar e mantenha a carga próxima ao corpo', 'Impulsione pelas pernas e quadris, depois guie o peso para a posição de recepção', 'Receba a carga com o tronco firme e os pés estáveis', 'Fique em pé para finalizar, depois desça o peso de forma controlada antes da próxima repetição']),
  ('4LIG9xr', 'Rosca scott inversa com barra', array['Sente-se em um banco scott com o peito apoiado e os braços estendidos para baixo, segurando uma barra com as palmas para baixo', 'Com os braços parados, expire e flexione a barra para cima enquanto contrai os bíceps', 'Apoie a parte superior do braço no banco scott e deixe o cotovelo livre para dobrar', 'Flexione o peso enquanto a parte superior dos braços permanece em contato com o apoio', 'Mantenha o tronco parado e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel']),
  ('4LoWllp', 'Puxada com pegada fechada com elástico fixo', array['Prenda o elástico em um ponto fixo acima de você, como uma barra fixa ou viga resistente', 'Sente-se em um banco ou cadeira de frente para o elástico, com os pés apoiados e os joelhos flexionados', 'Sente-se erguido e ajuste os ombros antes de puxar a alça para baixo', 'Puxe a alça para baixo levando os cotovelos em direção às costelas e mantenha o tronco firme', 'Controle o elástico na volta em vez de deixar que ele puxe você bruscamente', 'Deixe a alça subir de forma constante até que os braços estejam estendidos, depois reinicie os ombros']),
  ('4Ml7QFO', 'Elevação de pernas estendidas na barra', array['Fique pendurado em uma barra fixa com os braços retos e as palmas viradas para a frente', 'Contraia o tronco e eleve as pernas à sua frente, mantendo-as estendidas', 'Contraia o abdômen e mantenha os ombros ancorados no suporte', 'Eleve as pernas contraindo o tronco e movendo o quadril em vez de balançar', 'Frene as pernas antes que elas tirem a lombar da posição correta', 'Abaixe as pernas devagar sem balançar ou perder a posição do tronco']),
  ('4OaumBr', 'Remada suspensa', array['Prepare um fita de suspensão em uma altura adequada', 'Fique de frente para o ponto de ancoragem em uma base estável com os pés na largura dos ombros', 'Posicione o tronco e permita que os braços avancem sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem trancos no tronco', 'Estique os braços à frente novamente sem deixar o tronco balançar']),
  ('4QqYaJW', 'Rotação de tronco com apoio na bola suíça', array['Comece deitado de bruços em uma bola suíça com os pés na largura dos ombros e os dedos no chão', 'Coloque as mãos atrás da cabeça ou cruze-os sobre o peito', 'Estabilize a pelve e faça a rotação através da caixa torácica', 'Gire o tronco enquanto o quadril e a parte inferior do corpo permanecem o mais estáveis possível', 'Mantenha a bola firme e use os pés para controlar o equilíbrio', 'Retorne pelo centro antes de girar para o outro lado']),
  ('4U7iLb5', 'Pullover na máquina', array['Ajuste o assento e as alças da máquina articulada em uma posição confortável', 'Sente-se na máquina com as costas apoiadas no encosto e segure as alças com as palmas para baixo', 'Abaixe as costelas e mantenha uma pequena flexão nos cotovelos antes de descer o peso', 'Abaixe o peso em arco atrás da cabeça até sentir um estiramento confortável nos ombros', 'Mantenha as costelas abaixadas enquanto os braços passam por cima da cabeça', 'Puxe o peso de volta sobre o peito pelo mesmo arco, sem levantar as costelas']),
  ('4x5Okof', 'Supino sentado com elástico', array['Sente-se em uma cadeira ou banco com as costas retas e os pés apoiados', 'Segure as alças do elástico com as mãos, palmas para baixo e cotovelos flexionados a 90 graus', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre as alças para a frente mantendo o tronco firme', 'Controle o elástico na volta em vez de deixar que ele puxe você rapidamente', 'Desça o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('50BETrz', 'Barra fixa com pegada fechada e supinada', array['Suspensão na barra com as palmas voltadas para você e as mãos na largura dos ombros', 'Contraia o tronco e puxe-se em direção à barra, focando no uso dos bíceps para elevar o corpo', 'Comece de uma suspensão controlada com os ombros ativos e não soltos', 'Puxe os cotovelos para baixo e aproxime a parte superior do peito da barra sem chutar as pernas', 'Evite balançar as pernas para passar da barra', 'Desça até estender os braços sem soltar o corpo de uma vez do topo']),
  ('53Ttlck', 'Crucifixo inverso deitado com halteres', array['Posicione-se de bruços em um banco reto com um halter em cada mão, palmas viradas uma para a outra', 'Estenda os braços para baixo em direção ao chão, mantendo uma leve flexão nos cotovelos', 'Comece com uma carga moderada e uma pequena flexão nos cotovelos', 'Eleve os braços para os lados até a altura dos ombros sem inclinar o tronco ou encolher os ombros', 'Pare perto da altura dos ombros em vez de encolher os ombros para subir mais', 'Abaixe os braços lentamente para as laterais sem balançar o peso']),
  ('58rdhvL', 'Abdominal canivete com elástico', array['Deite-se de costas com as pernas esticadas e os braços estendidos para trás da cabeça, segurando o elástico', 'Contraia o abdômen e eleve as pernas e o tronco simultaneamente, trazendo as mãos em direção aos pés', 'Posicione a pelve e mantenha o pescoço relaxado antes de enrolar o tronco', 'Aproxime a caixa torácica da pelve, permitindo que o abdômen mova o tronco', 'Controle o elástico na volta em vez de deixar que ele puxe você rapidamente', 'Abaixe os ombros e o tronco com controle antes da próxima repetição']),
  ('5bpPTHv', 'Pistol squat com kettlebell', array['Fique em pé com os pés na largura dos ombros, segurando um kettlebell na altura do peito com ambas as mãos', 'Antes de se mover, tire o pé esquerdo do chão e estenda-o para a frente, mantendo-o paralelo ao solo', 'Contraia o abdômen e distribua a pressão por todo o pé de apoio', 'Estenda a perna livre para a frente enquanto agacha sobre a perna de apoio, mantendo o calcanhar no chão', 'Empurre para cima fazendo o peito e o quadril subirem juntos; evite que o joelho caia para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, e inicie a próxima descida']),
  ('5BZHW9s', 'Agachamento com desenvolvimento e rotação', array['Fique em pé com os pés na largura dos ombros e pontas dos pés levemente viradas para fora', 'Antes de se mover, abaixe o corpo em posição de agachamento flexionando os joelhos e empurrando o quadril para trás', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione o quadril e os joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos', 'Empurre para cima fazendo o peito e o quadril subirem juntos; evite que os joelhos caiam para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, e inicie a próxima descida']),
  ('5eLRITT', 'Stiff com halteres', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão com as palmas para baixo', 'Com as costas retas e o core contraído, flexione o quadril e desça os halteres em direção ao chão, permitindo uma leve flexão nos joelhos', 'Destrave os joelhos e contraia o abdômen antes de mover o quadril para trás', 'Empurre o quadril para trás mantendo a carga próxima e a coluna firme', 'Mantenha o peso próximo às pernas e pare quando as costas começarem a arredondar', 'Empurre o quadril para a frente para ficar erguido sem inclinar para trás no topo']),
  ('5fKX7wi', 'Extensão de tríceps unilateral sentado com halter e pegada invertida', array['Sente-se em um banco com as costas retas e os pés apoiados', 'Segure um halter com a palma voltada para cima e estenda o braço para cima acima da cabeça', 'Posicione a parte superior do braço antes de estender o cotovelo', 'Mantenha o braço apontado para cima e estenda o cotovelo sem abrir as costelas', 'Mantenha ambos os ombros nivelados e evite virar o tronco em direção ao braço em movimento', 'Flexione o cotovelo lentamente para retornar ao início da próxima repetição; altere os lados quando necessário']),
  ('5ipN0iE', 'Puxada assistida', array['Ajuste a máquina para o peso e altura desejados', 'Segure as alças com as palmas voltadas para baixo, um pouco além da largura dos ombros', 'Comece em uma suspensão controlada com os ombros ativos e não relaxados', 'Puxe os cotovelos para baixo e leve a parte superior do peito em direção à barra sem chutar as pernas', 'Evite balançar as pernas para passar da barra', 'Desça até esticar os braços sem cair repentinamente do topo']),
  ('5KLbZWx', 'Desenvolvimento alternado com kettlebell', array['Fique de pé com os pés na largura dos ombros, segurando um kettlebell em cada mão na altura dos ombros', 'Antes de se mover, empurre um kettlebell acima da cabeça, estendendo totalmente o braço', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as alças enquanto mantém o tronco contraído', 'Conclua o movimento de um lado antes que o outro lado comece', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente; alterne os lados quando a série exigir']),
  ('5lE7XRz', 'Remada curvada no Smith', array['Prepare a máquina Smith com a barra na altura do quadril', 'Fique de frente para a barra em uma postura estável com os pés na largura dos ombros', 'Posicione o tronco e permita que os braços se estendam para frente sem arredondar excessivamente', 'Puxe os cotovelos para trás e leve a barra ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem tracionar o tronco', 'Estenda os braços para frente novamente sem deixar o tronco oscilar']),
  ('5MRH8H2', 'Passo de esqui', array['Fique de pé com os pés na largura dos ombros', 'Flexione levemente os joelhos e mantenha a coluna em uma posição neutra e confortável', 'Comece em um ritmo que permita que os pés e os braços se movam em sincronia', 'Salte de um lado para o outro, aterrissando em um pé enquanto a outra perna passa por trás', 'Mantenha o padrão repetível à medida que a velocidade aumenta', 'Mantenha o ritmo pelo intervalo planejado, diminuindo a velocidade se a forma começar a falhar']),
  ('5uFK1xr', 'Extensão de tríceps com barra sentada', array['Sente-se em um banco com as costas retas e os pés apoiados', 'Segure uma barra com as palmas voltadas para baixo, mãos na largura dos ombros, e erga-a acima da cabeça', 'Posicione os braços antes de estender os cotovelos', 'Mantenha os braços apontados para cima e estenda os cotovelos sem abrir as costelas', 'Mantenha os braços firmes enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('5v7KYld', 'Supino inclinado no Smith', array['Ajuste o banco para uma inclinação de 30 a 45 graus', 'Sente-se no banco com as costas apoiadas no estofado e os pés firmemente no chão', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as alças enquanto mantém o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('5VCj6iH', 'Agachamento hack com barra', array['Comece ficando de pé com os pés na largura dos ombros e os dedos levemente virados para fora', 'Segure a barra por trás das pernas, apoiando-a na parte superior das coxas', 'Contraie o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para abaixar, mantendo os pés firmes e os joelhos alinhados com os dedos', 'Empurre para cima com o peito e o quadril subindo juntos; impeça que os joelhos desabem para dentro', 'Fique totalmente de pé, reajuste sua base e respiração, e inicie a próxima descida']),
  ('5vfAI0I', 'Desenvolvimento Scott com halteres', array['Sente-se em um banco com um halter em cada mão, palmas voltadas para frente', 'Antes de se mover, eleve os halteres até a altura dos ombros, com os cotovelos flexionados e as palmas voltadas para frente', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as alças enquanto mantém o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('5VXmnV5', 'Prancha lateral inclinada com peso corporal', array['Comece deitado de lado com as pernas estendidas e empilhadas uma sobre a outra', 'Apoie o antebraço no chão diretamente abaixo do ombro, com o cotovelo dobrado em um ângulo de 90 graus', 'Contraia o abdômen e encontre uma posição que consiga manter sem prender a respiração', 'Contraia a região central e mantenha a posição respirando normalmente', 'Continue respirando de forma estável enquanto mantém a mesma linha corporal', 'Mantenha a forma pelo tempo planejado e saia dela com controle']),
  ('5WiFcYk', 'Afundo com peso e balanço', array['Fique em pé com os pés na largura dos ombros, segurando um peso em cada mão', 'Dê um passo à frente com o pé direito, abaixando o corpo em uma posição de afundo', 'Posicione os ombros e deixe o peso mover-se para trás entre as pernas enquanto o quadril flexiona', 'Flexione para trás, depois empurre o quadril para a frente para projetar o peso para cima; deixe os braços guiarem', 'Deixe o quadril, e não os ombros, fornecer a força', 'Deixe o peso cair naturalmente e flexione novamente para o próximo balanço']),
  ('61GrD55', 'Rosca com pegada fechada deitado no cabo', array['Conecte uma barra reta a uma máquina de cabo com polia baixa', 'Deite-se de costas em um banco reto com os pés apoiados', 'Posicione os ombros e os braços antes de dobrar os cotovelos', 'Dobre os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados']),
  ('62Nw60O', 'Afundo reverso com barra', array['Fique em pé com os pés na largura dos ombros e segure uma barra na parte superior das costas', 'Dê um passo para trás com o pé direito, aterrissando na ponta do pé', 'Posicione sua base larga o suficiente para equilibrar antes de dobrar qualquer joelho', 'Entre no movimento e dobre ambos os joelhos, mantendo o pé da frente apoiado', 'Mantenha o pé da frente apoiado e evite colapsar para dentro no joelho', 'Empurre através do pé da frente para retornar ao início, depois alterne as pernas conforme planejado']),
  ('641mIfk', 'Supino inclinado com pegada reversa com barra', array['Incline o banco a aproximadamente 45 graus', 'Recline-se no banco e segure a barra com pegada reversa, mãos logo abaixo da largura dos ombros', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as manoplas para longe enquanto mantém o tronco contraído', 'Mantenha as palmas das mãos na pegada escolhida sem dobrar os punhos para trás', 'Abaixe o peso até a altura inicial sob controle antes de empurrar novamente']),
  ('67n3r98', 'Desenvolvimento para ombros na máquina', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure as manoplas com as palmas voltadas para baixo e posicione as mãos na altura dos ombros', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as manoplas para longe enquanto mantém o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial sob controle antes de empurrar novamente']),
  ('6bOA1Oi', 'Flexão lateral com peso (na bola suíça)', array['Sente-se em uma bola suíça com os pés na largura dos ombros e apoiados no chão', 'Pegue um peso em uma mão e coloque a outra mão no quadril', 'Fique em pé ou sentado erguido com a pelve voltada para a frente', 'Incline-se para o lado pela cintura sem torcer ou deixar o quadril se deslocar', 'Mantenha a bola estável e use os pés para gerenciar seu equilíbrio', 'Traga o peso ou o corpo de volta à posição inicial sem pressa']),
  ('6cKQC5E', 'Remada alta unilateral com halter', array['Fique em pé com os pés na largura dos ombros, segurando um halter em uma mão com a palma voltada para baixo', 'Deixe o halter pendurado com o braço estendido à frente das coxas, com a palma voltada para o corpo', 'Posicione o tronco e permita que os braços alcancem a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a manopla ou o peso em direção ao tronco', 'Mantenha ambos os ombros nivelados e resista a girar em direção ao braço de trabalho', 'Estenda os braços para a frente novamente sem deixar o tronco balançar; troque de lado quando a série pedir']),
  ('6CKUx7o', 'Extensão de tríceps deitada com barra EZ com pegada fechada atrás da cabeça', array['Apoie-se em um banco com os pés firmes e a cabeça na ponta do banco.', 'Segure a barra EZ com uma pegada fechada, palmas viradas para cima, e estenda os braços retos para cima do peito.', 'Posicione os braços antes de estender os cotovelos.', 'Mantenha os braços firmes e estenda pelos cotovelos para mover o peso.', 'Mantenha os braços firmes enquanto os antebraços se movimentam.', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição.']),
  ('6e2DcYX', 'Elevação de ombros inclinada com halteres', array['Ajuste um banco inclinado a um ângulo de 45 graus e sente-se nele com um halter em cada mão, palmas viradas para baixo.', 'Apoie os halteres nas coxas e recoste-se no banco.', 'Comece com uma carga viável e uma pequena flexão nos cotovelos.', 'Levante os pesos para longe do tronco até a altura dos ombros, mantendo os cotovelos levemente flexionados.', 'Pare perto da altura dos ombros em vez de encolher os ombros para levantar mais.', 'Abaixe os braços lentamente para os lados sem balançar o peso.']),
  ('6em2Dxj', 'Rosca martelo sentada alternada com halteres', array['Sente-se em um banco com um halter em cada mão, palmas viradas para o tronco e braços estendidos para baixo.', 'Mantenha a coluna em uma posição neutra e confortável e os cotovelos próximos ao tronco.', 'Posicione os ombros e os braços antes de flexionar os cotovelos.', 'Flexione com as palmas viradas uma para a outra e cotovelos perto dos lados; evite balançar para trás.', 'Termine o movimento de um lado antes que o outro lado comece.', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados; alterne os lados quando a série exigir.']),
  ('6FMU51h', 'Salto em semiagachamento', array['Fique em pé e ajuste os pés na largura dos ombros.', 'Antes de se mover, flexione os joelhos e abaixe o corpo em uma posição de agachamento.', 'Contraia o abdômen e espalhe a pressão por todo o pé.', 'Flexione nos quadris e joelhos para abaixar, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés.', 'Impulsione para cima com o peito e quadris subindo juntos; evite que os joelhos desabem para dentro.', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a próxima descida.']),
  ('6HiHHe0', 'Elevação de panturrilha em pé com barra', array['Fique em pé com os pés na largura dos ombros e segure uma barra na parte superior das costas.', 'Antes de se mover, eleve os calcanhares do chão o mais alto possível, equilibrando-se na parte da frente dos pés.', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel.', 'Suba pela parte da frente dos pés, levantando os calcanhares o mais alto que puder sem balançar.', 'Faça uma pausa no topo sem girar os tornozelos para fora.', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente.']),
  ('6HmFgmx', 'Elevação de panturrilha em pé (em uma escada)', array['Suba na borda de um degrau ou plataforma firme com os calcanhares pendurados e os dedos dos pés no degrau.', 'Use um corrimão ou parede para equilíbrio, se necessário.', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel.', 'Suba pela parte da frente dos pés, levantando os calcanhares o mais alto que puder sem balançar.', 'Faça uma pausa no topo sem girar os tornozelos para fora.', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente.']),
  ('6kSxYnw', 'Rosca de punho com barra', array['Apoie ambos os pés enquanto estiver sentado em um banco; com os joelhos flexionados.', 'Segure uma barra com as palmas viradas para cima e as mãos na largura dos ombros.', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou antebraço suportem a carga.', 'Mova-se pelos punhos ou dedos enquanto os antebraços permanecem apoiados e parados.', 'Use uma amplitude pequena e suave sem balançar os cotovelos.', 'Retorne ao início sem deixar a carga cair das mãos.']),
  ('6MaEjVA', 'Elevação de panturrilha em pé no Smith', array['Ajuste a barra da máquina Smith a uma altura que permita ficar em pé com os pés firmes e os ombros sob a barra.', 'Posicione-se sob a barra com os pés na largura dos ombros e os dedos apontados para frente.', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel.', 'Suba pela parte da frente dos pés, levantando os calcanhares o mais alto que puder sem balançar.', 'Faça uma pausa no topo sem girar os tornozelos para fora.', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente.']),
  ('6MfS53i', 'Tríceps testa com halter com um braço', array['Deite-se em um banco com um halter em uma mão e o braço esticado acima do peito', 'Abaixe o halter de forma controlada em direção à testa, mantendo a parte superior do braço fixa', 'Posicione os braços antes de estender os cotovelos', 'Mantenha os braços firmes e estenda os cotovelos para mover o peso', 'Mantenha a parte superior dos braços firme enquanto os antebraços se movem', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('6pTkI99', 'Desenvolvimento com um braço com halter', array['Fique em pé com os pés na largura dos ombros, segurando um halter em uma mão com as palmas voltadas para baixo', 'Flexione levemente os joelhos e incline o tronco para a frente nos quadris, com a coluna firme e o peito estufado', 'Contraia o abdômen antes da puxada e mantenha a carga próxima ao corpo', 'Impulsione com as pernas e quadris, depois guie o peso para a posição de recepção', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Fique em pé para finalizar, depois abaixe o peso de forma controlada antes da próxima repetição; alterne os lados quando necessário']),
  ('6sMAmNv', 'Rosca inversa com halter', array['Fique em pé com um halter em cada mão, palmas voltadas para o corpo e braços esticados', 'Com a parte superior dos braços fixa, expire e faça a rosca com os pesos enquanto contrai os bíceps', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Faça a rosca com as palmas voltadas para baixo, mantendo os cotovelos próximos e o tronco parado', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os braços estejam quase esticados, mantendo a parte superior dos braços parada']),
  ('6sYyrRX', 'Rotação de tronco deitado com joelhos flexionados', array['Deite-se de costas com os joelhos flexionados e os pés apoiados', 'Estenda os braços para os lados, perpendiculares ao corpo', 'Posicione a pelve e faça o giro através da caixa torácica', 'Gire pelo tronco enquanto os quadris e a parte inferior do corpo permanecem o mais firmes possível', 'Mantenha o giro suave em vez de lançar os braços pelo corpo', 'Retorne pelo centro antes de girar para o outro lado']),
  ('6t00BsF', 'Supino inclinado com um braço no cabo na bola suíça', array['Sente-se em uma bola suíça com os pés apoiados e as costas encostadas em um banco inclinado', 'Segure um puxador de cabo em uma mão e posicione o braço em um ângulo de 90 graus com o cotovelo flexionado', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores para longe enquanto mantém o tronco contraído', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente; alterne os lados quando necessário']),
  ('6TG6x2w', 'Rosca com barra EZ', array['Fique em pé com os pés na largura dos ombros e segure a barra EZ com as palmas voltadas para cima', 'Mantenha os cotovelos próximos ao tronco e a parte superior dos braços fixa durante todo o movimento', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os braços estejam quase esticados, mantendo a parte superior dos braços parada']),
  ('6vcvsLS', 'Elevação de pernas estendidas na barra', array['Suspenda-se em uma barra fixa com os braços esticados e as palmas voltadas para a frente', 'Contraia o tronco e levante as pernas à sua frente, mantendo-as esticadas', 'Contraia o abdômen e mantenha os ombros ancorados ao suporte', 'Levante as pernas contraindo o tronco e movendo-os nos quadris em vez de balançar', 'Desacelere as pernas antes que elas tirem a parte inferior das costas da posição', 'Abaixe as pernas lentamente sem balançar ou perder a posição do tronco']),
  ('6Wr0F3W', 'Elevação de pernas torcida', array['Deite-se de costas com as pernas estendidas e os braços ao lado do corpo', 'Flexione os joelhos e tire as pernas do chão, trazendo-as em direção ao peito', 'Contraia o abdômen e mantenha os ombros ancorados ao suporte', 'Levante as pernas contraindo o tronco e movendo-os nos quadris em vez de balançar', 'Desacelere as pernas antes que elas tirem a parte inferior das costas da posição', 'Abaixe as pernas lentamente sem balançar ou perder a posição do tronco']),
  ('6YUfHPL', 'Agachamento com peso corporal', array['Fique em pé e posicione os pés na largura dos ombros', 'Antes de se mover, abaixe o corpo dobrando os joelhos e empurrando os quadris para trás como se estivesse sentando em uma cadeira', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Dobre nos quadris e joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos desabem para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a descida seguinte']),
  ('6ZCiYWQ', 'Abdominal com braços cruzados no peito', array['Deite-se de costas com os joelhos dobrados e os pés apoiados', 'Cruze os braços sobre o peito', 'Posicione a pelve e mantenha o pescoço relaxado antes de curvar para cima', 'Curve a caixa torácica em direção à pelve, deixando os abdominais moverem o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão']),
  ('72BC5Za', 'Barra arqueira', array['Comece pendurado em uma barra fixa com as palmas voltadas para baixo, um pouco além da largura dos ombros', 'Contraia o tronco e puxe as escápulas para baixo e para trás', 'Comece a partir de uma suspensão controlada com os ombros ativos e não relaxados', 'Puxe os cotovelos para baixo e aproxime a parte superior do peito da barra sem chutar as pernas', 'Evite balançar as pernas para ultrapassar a barra', 'Desça até esticar os braços sem cair repentinamente do topo']),
  ('75Bgtjy', 'Agachamento sumô', array['Fique em pé e posicione os pés na largura dos ombros, com os dedos apontados levemente para fora', 'Antes de se mover, abaixe o corpo dobrando os joelhos e empurrando os quadris para trás como se estivesse sentando em uma cadeira', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Dobre nos quadris e joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos desabem para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a descida seguinte']),
  ('76vfTdU', 'Subida no banco com halteres e equilíbrio em uma perna com rosca bíceps', array['Posicione-se em frente a um degrau ou plataforma segurando um halter em cada mão, com as palmas voltadas para o corpo', 'Coloque o pé direito no degrau, garantindo que todo o pé esteja em contato com a superfície', 'Posicione os ombros e a parte superior dos braços antes de dobrar os cotovelos', 'Dobre os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco firme e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os braços estejam quase retos, mantendo a parte superior dos braços parada']),
  ('7858za8', 'Subida no banco com avanço com halteres', array['Posicione-se em frente a um degrau ou plataforma segurando um halter em cada mão, com as palmas voltadas para os lados', 'Coloque o pé direito no degrau, garantindo que todo o pé esteja na superfície', 'Coloque o pé da frente totalmente na plataforma antes de transferir o peso para ele', 'Suba na plataforma e empurre pelo pé da frente para ficar erguido sobre ele', 'Mantenha o pé da frente apoiado e evite que o joelho desabe para dentro', 'Empurre pelo pé da frente para retornar ao início, depois troque de perna conforme planejado']),
  ('78VqWQK', 'Supino inclinado no Smith com pegada reversa', array['Ajuste o assento do aparelho Smith em um ângulo de inclinação confortável', 'Sente-se no aparelho com as costas apoiadas no encosto e os pés firmes no chão', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as barras para longe mantendo o tronco contraído', 'Mantenha as palmas das mãos na pegada escolhida sem dobrar os punhos para trás', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('79AmJsI', 'Rosca martelo com halteres', array['Fique em pé e erguido com um halter em cada mão, com as palmas voltadas para o tronco', 'Mantenha os cotovelos próximos ao tronco e gire as palmas das mãos até que fiquem voltadas para a frente', 'Posicione os ombros e a parte superior dos braços antes de dobrar os cotovelos', 'Faça a rosca com as palmas voltadas uma para a outra e os cotovelos próximos às costelas; evite balançar para trás', 'Mantenha as palmas voltadas uma para a outra e os punhos retos', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços parada']),
  ('7AnZtSv', 'Rosca de punho unilateral com halteres no banco', array['Apoie ambos os pés sentado em um banco e segure um halter em uma mão com a palma voltada para baixo', 'Apoie o antebraço no banco com o punho para fora da borda', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço suportem a carga', 'Movimente apenas os punhos ou dedos enquanto os antebraços permanecem apoiados e parados', 'Mantenha ambos os ombros nivelados e evite girar o tronco em direção ao braço em movimento', 'Retorne à posição inicial sem deixar a carga escapar das mãos e alterne os lados quando necessário']),
  ('7aolH9D', 'Arremesso de bola medicinal no peito com repetições múltiplas', array['Fique em pé com os pés na largura dos ombros, segurando uma bola medicinal na altura do peito', 'Estenda os braços para a frente, empurrando a bola medicinal para longe do peito', 'Adote uma postura firme e certifique-se de que há espaço livre suficiente para o trajeto da bola', 'Empurre a bola com força usando os braços e o tronco em conjunto; pegue-a de volta antes de reiniciar', 'Acompanhe o movimento com o corpo inteiro, mantendo o controle no momento da recepção', 'Traga o peso ou o corpo de volta à posição inicial sem pressa']),
  ('7aVz15j', 'Mergulho de tríceps no chão', array['Sente-se na borda de uma cadeira ou banco com as mãos ao lado dos quadris e os dedos apontados para a frente', 'Retire o quadril da frente da cadeira com as pernas estendidas à sua frente', 'Posicione os ombros para baixo e mantenha os cotovelos apontados principalmente para trás', 'Flexione os cotovelos para abaixar o corpo entre os apoios e pare em uma profundidade confortável para os ombros', 'Escolha uma profundidade que permita manter os ombros confortáveis', 'Empurre o chão com as mãos para subir e ajuste os ombros antes da próxima repetição']),
  ('7B4F5nZ', 'Elevação de panturrilha na máquina', array['Ajuste o assento da máquina para que seus ombros fiquem alinhados com o apoio', 'Apoie a ponta dos pés na plataforma com os calcanhares para fora da borda', 'Permita que os tornozelos se movam livremente enquanto o resto do corpo permanece firme', 'Suba na ponta dos pés, elevando os calcanhares o máximo possível sem balançar', 'Faça uma pausa no topo sem girar os tornozelos para fora', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente']),
  ('7Ba7bQ2', 'Remada alta com kettlebell com dois braços', array['Fique em pé com os pés na largura dos ombros, segurando um kettlebell na frente das coxas com ambas as mãos e palmas voltadas para você', 'Flexione levemente os joelhos e incline o quadril para a frente, abaixando o kettlebell em direção ao solo', 'Contraia o abdômen antes de puxar e mantenha a carga próxima ao corpo', 'Impulsione com as pernas e o quadril, guiando o peso para a posição de recepção', 'Receba a carga com o tronco firme e os pés estáveis', 'Fique em pé para finalizar o movimento e abaixe o peso de forma controlada antes da próxima repetição']),
  ('7D5bgLT', 'Rosca scott unilateral com halter', array['Sente-se em um banco scott com os pés apoiados no chão', 'Segure um halter em uma mão com a palma voltada para cima e apoie o braço no suporte scott', 'Posicione a parte superior do braço firmemente contra o suporte e deixe o cotovelo livre para flexionar', 'Flexione o peso enquanto a parte superior do braço permanece em contato com o suporte', 'Mantenha o tronco parado e use a flexão do cotovelo para levantar o peso', 'Abaixe o peso até que os braços estejam quase esticados, mantendo a parte superior do braço imóvel']),
  ('7E06s6d', 'Flexão com toque no peito', array['Inicie em posição de prancha alta com as mãos ligeiramente além da largura dos ombros e o corpo em linha reta', 'Abaixe o corpo em direção ao solo flexionando os cotovelos e mantendo-os próximos às costelas', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito mantendo o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre o corpo de volta até esticar os braços, mantendo a linha do corpo intacta']),
  ('7ePTw4B', 'Alongamento de tríceps sentado na bola suíça', array['Sente-se em uma bola suíça com os pés apoiados e as costas retas', 'Segure um halter com uma mão e estenda o braço diretamente para cima acima da cabeça', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento', 'Mova-se em direção ao alongamento até sentir uma tensão leve; continue respirando e evite balançar', 'Mantenha a bola estável e use os pés para controlar o seu equilíbrio', 'Mantenha a posição com respiração constante e retorne suavemente; repita do outro lado, se necessário']),
  ('7F1DVzn', 'Puxada frontal na máquina', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure os puxadores com as palmas voltadas para baixo, um pouco além da largura dos ombros', 'Sente-se erguido e posicione os ombros antes de puxar o puxador para baixo', 'Puxe o puxador para baixo direcionando os cotovelos em direção às costelas; mantenha o tronco firme', 'Puxe com os cotovelos em vez de se inclinar muito para trás para mover o puxador', 'Deixe o puxador subir de forma constante até que os braços estejam estendidos e, em seguida, ajuste os ombros']),
  ('7f2jsqP', 'Rotação sentada com um halter', array['Sente-se em um banco com as costas retas e segure um halter em uma das mãos, apoiando-o na coxa', 'Antes de se mover, eleve o halter até a altura do ombro, mantendo o cotovelo próximo ao corpo', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço suportem a carga', 'Mude o movimento pelos punhos ou dedos enquanto os antebraços permanecem apoiados e parados', 'Mantenha ambos os ombros nivelados e evite virar-se em direção ao braço que está trabalhando', 'Retorne à posição inicial sem deixar a carga cair das mãos; alterne os lados quando a série exigir']),
  ('7gdLIXa', 'Supino com halteres com pegada neutra deitado', array['Acomode-se em um banco com um halter em cada mão, palmas viradas uma para a outra e braços estendidos para cima', 'Antes de se mover, abaixe os halteres para as laterais do peito, mantendo os cotovelos em um ângulo de 90 graus', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para longe enquanto mantém o tronco contraído', 'Mantenha as palmas viradas uma para a outra e os punhos retos', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('7HcfMBP', 'Tríceps em pé assistido com toalha', array['Fique em pé com os pés na largura dos ombros e segure uma toalha com as duas mãos atrás da cabeça', 'Mantenha os cotovelos próximos às orelhas e a parte superior dos braços imóvel', 'Posicione a parte superior dos braços no lugar antes de estender os cotovelos', 'Mantenha a parte superior dos braços firme e estenda através dos cotovelos para mover o peso', 'Mantenha a parte superior dos braços firme enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('7Hg55JG', 'Remada alta com halteres', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão com as palmas voltadas para baixo', 'Flexione os joelhos e abaixe o quadril em posição de agachamento, com a coluna firme e o peito estufado', 'Contraia o abdômen antes de puxar e mantenha a carga próxima ao corpo', 'Empurre com as pernas e o quadril e, em seguida, guie o peso para a posição de recebimento', 'Receba a carga com o tronco contraído e os pés estáveis', 'Fique em pé para finalizar e, em seguida, abaixe o peso com controle antes da próxima repetição']),
