  ('7I6LNUG', 'Remada sentada na máquina', array['Ajuste a altura do assento e dos apoios para os pés em uma posição confortável', 'Sente-se na máquina com o peito apoiado no encosto e os pés nos apoios', 'Posicione o tronco e permita que os braços alcancem a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga o puxador ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços para a frente novamente sem deixar o tronco despencar']),
  ('7inpWch', 'Rosca concentrada em pé com halter', array['Fique em pé com os pés na largura dos ombros e segure um halter em uma das mãos, com o braço reto e a palma voltada para dentro', 'Posicione a mão oposta na coxa para dar suporte', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel']),
  ('7jGOBF3', 'Desenvolvimento fechado com halteres com pegada neutra', array['Sente-se em um banco reto com um halter em cada mão, apoiados nas coxas', 'Use as coxas para ajudar a levantar os halteres, erguendo-os um de cada vez para segurá-los na altura dos ombros', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para cima mantendo o tronco firme', 'Mantenha os punhos alinhados e use uma trajetória de ombro natural', 'Desça o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('7M66AVi', 'Extensão com barra no solo', array['Ajoelhe-se no chão e segure uma barra com as duas mãos, na largura dos ombros', 'Guie a barra para a frente, estendendo os braços e mantendo o core contraído', 'Aperte o abdômen e mantenha a pelve encaixada antes de esticar os braços', 'Estique os braços mantendo costelas e pelve alinhadas; pare antes da lombar curvar', 'Pare o movimento quando a lombar começar a curvar', 'Retorne ao início usando os ombros e o abdômen, mantendo a mesma linha corporal']),
  ('7OeHptV', 'Barra fixa com apoio em pé', array['Ajuste a máquina para o nível de assistência desejado', 'Suba na plataforma e segure as alças com as palmas voltadas para baixo, um pouco além da largura dos ombros', 'Comece de uma suspensão controlada com os ombros ativos e não soltos', 'Puxe os cotovelos para baixo e aproxime a parte superior do peito da barra sem chutar as pernas', 'Evite balançar as pernas para passar da barra', 'Desça com os braços estendidos sem soltar de repente do topo']),
  ('7R4NIjL', 'Tríceps em pé com apoio e toalha', array['Fique em pé com os pés na largura dos ombros e segure uma toalha com as duas mãos atrás da cabeça', 'Mantenha os cotovelos próximos às orelhas e os braços parados', 'Posicione a parte superior dos braços no lugar antes de estender os cotovelos', 'Mantenha os braços firmes e estenda os cotovelos para mover o peso', 'Mantenha a parte superior dos braços firme enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('7RWNjiB', 'Pronação deitado com halteres no chão', array['Deite-se no chão de bruços com os braços estendidos para a frente, segurando um halter em cada mão', 'Gire as palmas das mãos para baixo em direção ao chão', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou antebraço suportem a carga', 'Movimente os punhos ou dedos enquanto os antebraços permanecem apoiados e parados', 'Use uma amplitude pequena e suave sem balançar os cotovelos', 'Retorne ao início sem deixar a carga cair das mãos']),
  ('7saC5zz', 'Crucifixo declinado no cabo', array['Ajuste a polia na posição declinada', 'Fique de costas para a máquina com uma base estável e pés na largura dos ombros', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços', 'Com uma leve flexão nos cotovelos, junte os braços em um arco largo', 'Mantenha o ângulo do cotovelo quase inalterado durante o arco', 'Abra os braços de volta pelo mesmo arco sem deixar a carga cair']),
  ('7uFJuXp', 'Passada ajoelhada com peso e balanço', array['Comece em posição de joelhos com os joelhos na largura dos quadris e as costas retas', 'Segure um peso em cada mão, com os braços estendidos para baixo na sua frente', 'Posicione os ombros e deixe o peso ir para trás entre as pernas enquanto o quadril flexiona', 'Flexione o quadril para trás, depois empurre o quadril para frente para projetar o peso para cima, guiando com os braços', 'Deixe o quadril, e não os ombros, gerar a força', 'Deixe o peso cair naturalmente e flexione o quadril novamente para o próximo balanço']),
  ('7vG5o25', 'Remada inclinada com halteres', array['Ajuste o banco para aproximadamente 45 graus', 'Segure um halter em cada mão e sente-se no banco com o peito apoiado na inclinação', 'Posicione o tronco e permita que os braços se estendam para a frente sem arredondar excessivamente', 'Puxe os cotovelos para trás e traga o peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços para a frente novamente sem deixar o tronco balançar']),
  ('7w6i0vE', 'Desenvolvimento alternado com kettlebell no chão', array['Deite-se de costas no chão com os joelhos flexionados e os pés apoiados', 'Segure um kettlebell em cada mão com as palmas voltadas para os pés e os braços estendidos para cima', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para cima mantendo o tronco firme', 'Conclua o movimento de um lado antes de iniciar o outro', 'Desça o peso de forma controlada até a altura inicial antes de empurrar novamente e alterne os lados conforme necessário']),
  ('7WaDzyL', 'Abdução de quadril lateral', array['Fique em pé com os pés na largura dos ombros e as mãos na cintura', 'Transfira o peso para uma perna e eleve a perna oposta para o lado mantendo-a esticada', 'Contraia o abdômen e mantenha os ombros firmes no apoio', 'Abra as pernas contra a resistência sem mover o tronco', 'Desacelere as pernas antes que elas tirem a lombar da posição', 'Abaixe as pernas lentamente sem balançar ou perder a posição do tronco']),
  ('7WcQgkm', 'Extensão de tríceps inclinada no Smith', array['Ajuste o banco da máquina Smith para que a barra fique na altura dos ombros', 'Sente-se no banco com as costas apoiadas no encosto e os pés firmes no chão', 'Posicione os braços antes de estender os cotovelos', 'Mantenha os braços firmes e estenda os cotovelos para mover o peso', 'Mantenha os braços parados enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('7xeukSt', 'Merguho para escápula', array['Fique em pé com os pés na largura dos ombros e os braços estendidos à frente', 'Flexione levemente os joelhos eincline o tronco para a frente com a coluna firme', 'Abaixe os ombros e mantenha os cotovelos apontados para trás', 'Flexione os cotovelos para abaixar entre os apoios parando em uma profundidade confortável para os ombros', 'Escolha uma profundidade que permita manter os ombros confortáveis', 'Empurre com as mãos para subir e ajuste os ombros antes de outra repetição']),
  ('7xI5MXA', 'Supino no cabo', array['Ajuste a máquina de cabo na altura do peito e prenda os puxadores', 'Fique de costas para a máquina em uma base estável com os pés na largura dos ombros', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre os puxadores para a frente mantendo o tronco firme', 'Mantenha os punhos alinhados e use um trajeto de ombro natural', 'Desça o peso de forma controlada até a altura inicial antes de empurrar novamente']),
  ('7y9JIMj', 'Rosca scott inversa na máquina', array['Ajuste o assento ao seu corpo e posicione-se na máquina', 'Segure os puxadores com as palmas voltadas para cima', 'Apoie a parte superior do braço no apoio scott deixando o cotovelo livre para flexionar', 'Flexione o peso enquanto os braços permanecem em contato com o apoio', 'Mantenha as palmas na pegada escolhida sem curvar os punhos para trás', 'Desça até que os cotovelos estejam quase retos mantendo os braços parados']),
  ('7zdxRTl', 'Leg press no Smith', array['Ajuste o assento e a plataforma do Smith em uma posição confortável', 'Sente-se na máquina com as costas apoiadas no encosto e os pés na largura dos ombros na plataforma', 'Apoie os pés firmemente na plataforma e mantenha o quadril contra o assento', 'Flexione os joelhos para aproximar a plataforma e depois empurre-a com os pés', 'Interrompa a descida antes que o quadril se descole do assento', 'Retorne pelo mesmo caminho em um ritmo controlado']),
  ('82LxxkW', 'Rosca de punho com barra', array['Apoie ambos os pés sentado em um banco com os antebraços apoiados nas coxas e segurando uma barra com as palmas para cima', 'Deixe a barra rolar até os dedos mantendo os punhos retos', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão e do antebraço suportem a carga', 'Movimente os punhos ou os dedos enquanto os antebraços permanecem apoiados e parados', 'Use uma amplitude curta e suave sem balançar os cotovelos', 'Retorne ao início sem deixar a carga escapar das mãos']),
  ('83HoW9X', 'Remada alta com barra', array['Fique de pé com os pés na largura dos ombros e segure uma barra com as palmas para baixo, mãos logo além da largura dos ombros.', 'Mantenha a barra pendurada à frente das coxas, com os braços retos.', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e leve a barra ou peso em direção ao tronco.', 'Traga os cotovelos para trás sem dar trancos no tronco.', 'Estenda os braços para a frente novamente sem deixar o tronco balançar.']),
  ('84RyJf8', 'Desenvolvimento unilateral com halter', array['Fique de pé com os pés na largura dos ombros e segure um halter em uma das mãos na altura do ombro, com a palma voltada para a frente.', 'Empurre o halter para cima até que o braço esteja reto acima da cabeça.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso para longe mantendo o tronco contraído.', 'Mantenha ambos os ombros nivelados e resista a girar em direção ao braço que está trabalhando.', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente; alterne os lados quando necessário.']),
  ('84sESNy', 'Rosca bicep unilateral sentada com halter na bola suíça com perna elevada', array['Sente-se em uma bola suíça com os pés apoiados e as costas retas.', 'Segure um halter em uma das mãos com a palma voltada para cima e o braço reto.', 'Posicione os ombros e braços antes de flexionar os cotovelos.', 'Flexione os cotovelos para levar o peso em direção aos ombros sem balançar o tronco.', 'Mantenha ambos os ombros nivelados e resista a girar em direção ao braço que está trabalhando.', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados; alterne os lados quando necessário.']),
  ('89HVjEp', 'Desenvolvimento sentado com kettlebell', array['Sente-se em um banco com as costas retas e os pés apoiados.', 'Segure um kettlebell em cada mão na altura dos ombros, com as palmas voltadas para a frente.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso para longe mantendo o tronco contraído.', 'Mantenha os punhos alinhados e use um caminho para os ombros que pareça natural.', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente.']),
  ('8ARQ9Hw', 'Puxada alta sumô com kettlebell', array['Fique de pé com os pés mais afastados que a largura dos ombros e os dedos apontados para fora.', 'Segure um kettlebell com ambas as mãos à frente do corpo, com os braços estendidos para baixo.', 'Contraia o abdômen antes da puxada e mantenha a carga próxima ao corpo.', 'Impulsione a partir da base larga e puxe o kettlebell em direção à parte superior do peito, liderando com os cotovelos.', 'Receba a carga com o tronco contraído e os pés estáveis.', 'Fique erguido para finalizar, depois abaixe o peso com controle antes da próxima repetição.']),
  ('8coXSYU', 'Flexão e retração de ombros sentada com rolo', array['Sente-se em uma superfície plana com as pernas estendidas à sua frente.', 'Segure o rolo com ambas as mãos, palmas para baixo, e coloque-o sobre as coxas.', 'Contraia o abdômen e mantenha a pelve encaixada antes de estender os braços.', 'Role o rolo para longe ao longo das pernas conforme os braços se estendem para a frente, depois traga-o de volta para as coxas.', 'Pare de estender quando a parte inferior das costas começar a arquear.', 'Puxe de volta para o início usando os ombros e o abdômen, mantendo a mesma linha corporal.']),
  ('8d8qJQI', 'Remada inclinada com barra em pegada inversa', array['Ajuste o banco para aproximadamente 45 graus.', 'Sente-se no banco de frente para o encosto com o peito apoiado nele.', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e leve a barra ou peso em direção ao tronco.', 'Mantenha as palmas na pegada escolhida sem dobrar os punhos para trás.', 'Estenda os braços para a frente novamente sem deixar o tronco balançar.']),
  ('8DiFDVA', 'Crucifixo inverso com halteres', array['Fique de pé com os pés na largura dos ombros e segure um halter em cada mão.', 'Flexione levemente os joelhos e incline o tronco para a frente a partir dos quadris, com a coluna firme.', 'Mantenha uma leve flexão nos cotovelos e ajuste os ombros antes de mover os braços.', 'Com uma leve flexão nos cotovelos, faça um arco amplo abrindo os braços.', 'Mantenha o ângulo dos cotovelos quase inalterado durante o arco.', 'Abra os braços de volta pelo mesmo arco sem deixar a carga cair.']),
  ('8eqjhOl', 'Supino inclinado com halteres com pegada neutra', array['Ajuste o banco em aproximadamente 45 graus', 'Sente-se no banco com as costas apoiadas no encosto e os pés firmes no chão', 'Estabilize o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para cima mantendo o tronco firme', 'Mantenha os punhos alinhados e use uma trajetória de ombro natural', 'Desça o peso até a altura inicial de forma controlada antes de empurrar novamente']),
