  ('8oYqOt9', 'Rosca sentada no cabo', array['Sente-se em uma máquina de cabo com os pés apoiados e as costas retas', 'Segure o acessório do cabo com as palmas viradas para cima e os braços esticados', 'Posicione os ombros e os braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso', 'Desça até que os cotovelos estejam quase esticados, mantendo os braços parados']),
  ('8ozhUIZ', 'Elevação de panturrilha em pé com barra', array['Fique em pé com os pés na largura dos ombros e apoie uma barra na parte superior das costas', 'Antes de se mover, levante os calcanhares do chão o mais alto possível, usando apenas os dedos dos pés', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel', 'Suba na ponta dos pés, levantando os calcanhares o mais alto que puder sem oscilar', 'Faça uma pausa no topo sem girar os tornozelos para fora', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente']),
  ('8urJS9b', 'Extensão lombar com peso (na bola suíça)', array['Posicione-se de bruços em uma bola suíça com o quadril apoiado na bola e os pés contra a parede para estabilidade', 'Coloque as mãos atrás da cabeça ou cruze-as sobre o peito', 'Fixe o quadril e os pés no apoio antes de elevar', 'Eleve o tronco ou as pernas até alinharem com o corpo, sem arquear excessivamente a lombar', 'Mantenha a bola firme e use os pés para controlar o equilíbrio', 'Retorne pelo mesmo caminho em ritmo controlado']),
  ('8xUv4J7', 'Abdominal sentado no cabo', array['Sente-se em uma máquina de cabo com os pés apoiados e os joelhos flexionados', 'Segure a alça do cabo com as duas mãos e posicione-a atrás da cabeça', 'Posicione a pelve e mantenha o pescoço relaxado antes de flexionar para cima', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão']),
  ('8yBgwBS', 'Rosca concentrada no cabo', array['Sente-se em um banco ou cadeira com os pés apoiados e os joelhos flexionados', 'Segure a alça do cabo com as palmas para cima e apoie o cotovelo contra a parte interna da coxa', 'Posicione os ombros e os braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo erguer o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados']),
  ('903mzG8', 'Desenvolvimento de ombros no Smith', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure a barra com as palmas voltadas para baixo, logo além da largura dos ombros', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para longe enquanto mantém o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial sob controle antes de empurrar novamente']),
  ('945zpRg', 'Supino reto com pegada inversa e aberta', array['Acomode-se em um banco com os pés apoiados e as costas pressionadas contra o banco', 'Segure a barra com uma pegada inversa e aberta, logo além da largura dos ombros', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para longe enquanto mantém o tronco contraído', 'Mantenha as palmas na pegada escolhida sem dobrar os punhos para trás', 'Abaixe o peso até a altura inicial sob controle antes de empurrar novamente']),
  ('99rWm7w', 'Alongamento de posteriores de coxa', array['Fique em pé e posicione os pés na largura dos ombros', 'Dê um passo à frente com o pé direito e transfira o peso para a perna direita', 'Acomode-se na posição inicial e respire suavemente antes de aprofundar', 'Aproxime-se do alongamento até sentir uma tensão leve; continue respirando e evite balançar', 'Permaneça em um alongamento leve em vez de puxar mais com impulso', 'Mantenha a posição com respiração constante, depois solte suavemente; repita do outro lado se necessário']),
  ('9Ap7miY', 'Abdominal declinado', array['Acomode-se em um banco declinado com os pés presos e os joelhos flexionados a 90 graus', 'Coloque as mãos atrás da cabeça ou cruzadas no peito', 'Posicione a pelve e mantenha o pescoço relaxado antes de flexionar para cima', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão']),
  ('9c6T1YX', 'Mountain climber cruzado', array['Inicie em posição de prancha alta com as mãos diretamente sob os ombros e o corpo em linha reta', 'Contraia o tronco e retire o pé direito do solo, trazendo o joelho direito em direção ao cotovelo esquerdo', 'Contraia o tronco levemente antes de mover um membro', 'Mova o braço ou a perna em atividade mantendo o tronco firme e a respiração constante', 'Evite que a pelve balance enquanto o braço ou a perna se move', 'Reajuste sua postura antes de trocar de lado ou iniciar a próxima repetição']),
  ('9E25EOx', 'Afundo búlgaro', array['Fique em pé com os pés na largura dos ombros', 'Dê um passo à frente com um pé e posicione-o a cerca de 60 centímetros na frente do outro', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para descer, mantendo os pés apoiados no chão e os joelhos alinhados com os dedos dos pés', 'Empurre para cima fazendo o peito e o quadris subirem juntos; impeça que os joelhos desabem para dentro', 'Fique completamente em pé, ajuste sua base e respiração, e então inicie a próxima descida']),
  ('9fCHfSc', 'Remada com rotação de palma no cabo', array['Conecte um puxador a uma máquina de cabo na altura da cintura', 'Fique de frente para a máquina em uma postura estável com os pés na largura dos ombros', 'Posicione o tronco e permita que os braços se estendam para a frente sem arredondar excessivamente', 'Puxe os cotovelos para trás e traga o puxador ou peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos com o tronco', 'Estenda os braços para a frente novamente sem deixar o tronco oscilar']),
  ('9gbyYKk', 'Rotação interna de quadril sentado com elástico', array['Sente-se em uma cadeira ou banco com as costas retas e os pés apoiados', 'Posicione um elástico de resistência ao redor das coxas, logo acima dos joelhos', 'Posicione a pelve e faça o giro através da caixa torácica', 'Gire através do tronco enquanto os quadris e a parte inferior do corpo permanecem o mais estáveis possível', 'Controle o elástico no caminho de volta em vez de deixar que ele puxe você de volta', 'Retorne pelo centro antes de girar para o outro lado']),
  ('9GXrTE6', 'Elevação de panturrilha unilateral no solo no Smith', array['Posicione-se no chão sob a barra da máquina Smith, virado de costas para a máquina', 'Apoie a parte anterior dos pés em uma superfície elevada, como uma anilha ou bloco', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel', 'Eleve-se através da parte anterior dos pés, levantando os calcanhares o mais alto que puder sem balançar', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o trabalho', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente; alterne os lados quando necessário']),
  ('9IxJdtC', 'Elevação de quadril deitado', array['Deite-se de costas com as pernas estendidas e os braços ao lado do corpo', 'Posicione as mãos sob os glúteos para dar suporte', 'Apoie os pés no chão e evite estufar as costelas enquanto os quadris se prepararam para subir', 'Pressione através dos pés e eleve os quadris até que seu tronco e coxas fiquem alinhados', 'Pare quando os quadris estiverem alinhados com o tronco; não arqueie mais a parte inferior das costas', 'Abaixe os quadris de forma constante e mantenha os pés apoiados para a próxima elevação']),
  ('9JprnPh', 'Elevação de panturrilha unilateral com elástico', array['Fique em pé com os pés na largura dos quadris e coloque o elástico ao redor da parte anterior do pé esquerdo', 'Use um objeto estável para manter o equilíbrio, se necessário', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel', 'Eleve-se através da parte anterior dos pés, levantando os calcanhares o mais alto que puder sem balançar', 'Controle o elástico no caminho de volta em vez de deixar que ele puxe você de volta', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente']),
  ('9KU9TYF', 'Leg press horizontal unilateral', array['Ajuste o assento da máquina para que seus joelhos fiquem em um ângulo de 90 graus quando seus pés estiverem na plataforma', 'Sente-se na máquina com as costas apoiadas no encosto e os pés na largura dos ombros na plataforma', 'Apoie os pés firmemente na plataforma e mantenha os quadris contra o assento', 'Flexione os joelhos para trazer a plataforma em sua direção, depois empurre-a para longe através dos pés', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o trabalho', 'Retorne pelo mesmo caminho em um ritmo controlado; alterne os lados quando necessário']),
  ('9n2149Z', 'Agachamento deitado no trenó', array['Ajuste a máquina de trenó para um peso confortável', 'Deite-se de costas na máquina de trenó com os pés na plataforma', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para descer, mantendo os pés apoiados no chão e os joelhos alinhados com os dedos dos pés', 'Empurre para cima fazendo o peito e o quadris subirem juntos; impeça que os joelhos desabem para dentro', 'Fique completamente em pé, ajuste sua base e respiração, e então inicie a próxima descida']),
  ('9pa4H5m', 'Press Pallof horizontal com elástico', array['Conecte o elástico a um ponto de fixação firme na altura da cintura', 'Fique em pé de lado para o ponto de fixação com os pés na largura dos ombros', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as alças para longe mantendo o tronco firme', 'Controle o elástico na volta em vez de deixar que ele puxe você de volta', 'Desça o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('9pQSkH8', 'Remada com dois braços com halteres no banco inclinado em pegada inversa', array['Ajuste o banco para aproximadamente 45 graus', 'Sente-se no banco com o peito apoiado no encosto e os pés firmes no chão', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao tronco', 'Mantenha as palmas das mãos na pegada escolhida sem dobrar os punhos para trás', 'Estique os braços para a frente novamente sem deixar o tronco balançar']),
  ('9RT8oQW', 'Mergulho no banco no chão', array['Sente-se na borda de um banco ou cadeira com as mãos segurando a borda e os dedos apontados para a frente', 'Retire o quadril do banco apoiando seu peso com as mãos', 'Abaixe os ombros e mantenha os cotovelos apontados principalmente para trás', 'Dobre os cotovelos para descer entre os apoios e pare em uma profundidade confortável para os ombros', 'Escolha uma profundidade que permita que os ombros fiquem confortáveis', 'Empurre com as mãos para subir e ajuste os ombros antes de outra repetição']),
