  ('aqvSOQE', 'Crucifixo inverso no crossover com cabos', array['Conecte um puxador D em cada cabo da polia baixa e fique no meio da máquina de crossover', 'Segure os puxadores com pegada pronada (palmas para baixo) e dê um passo à frente, posicionando os pés na largura dos ombros', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços', 'Traga os puxadores pela frente do peito em um arco amplo, mantendo uma leve flexão nos cotovelos', 'Mantenha o ângulo do cotovelo quase inalterado durante o arco', 'Abra os braços de volta pelo mesmo arco sem deixar a carga cair']),
  ('AR0ig3o', 'Abdominal com flexão de pernas (joelhos flexionados)', array['Deite-se de costas com os joelhos flexionados e os pés apoiados no chão', 'Coloque as mãos atrás da cabeça com os cotovelos apontando para fora', 'Posicione a pelve e mantenha o pescoço relaxado antes de subir', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima repetição']),
  ('arsYEd3', 'Afundo unilateral com elástico', array['Fique em pé com os pés na largura dos quadris e coloque um elástico de resistência ao redor dos tornozelos', 'Leve uma perna para a frente e apoie o peito do pé em um banco ou degrau atrás de você', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para descer, mantendo os pés firmes no chão e os joelhos alinhados com os dedos dos pés', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Levante-se completamente, ajuste sua postura e respiração, depois comece a próxima descida; alterne os lados quando necessário']),
  ('arvaszz', 'Flexão modificada com apoio nos braços', array['Comece em posição de flexão com as mãos diretamente abaixo dos ombros e o corpo em linha reta', 'Abaixe o corpo em direção ao chão flexionando os cotovelos, mantendo-os próximos ao corpo', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito mantendo o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre para voltar aos braços esticados, mantendo a linha do corpo intacta']),
  ('aTNKZiC', 'Elevação lateral unilateral inclinada com halteres', array['Sente-se em um banco inclinado com um halter em uma mão, apoiando-o na coxa', 'Incline-se para a frente e posicione o braço contra a parte interna da coxa', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos', 'Eleve os braços para as laterais até a altura dos ombros, sem inclinar o tronco ou encolher os ombros', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Abaixe os braços lentamente até as laterais sem balançar o peso; alterne os lados quando necessário']),
  ('aumB2IV', 'Abdominal com auxílio', array['Sente-se na borda do banco ou peça a um parceiro para segurar seus pés', 'Deite-se de costas com os joelhos flexionados e os pés apoiados no chão', 'Posicione a pelve e mantenha o pescoço relaxado antes de subir', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima repetição']),
  ('aVs3BR3', 'Rotação de tronco no cabo', array['Fique em pé com os pés na largura dos ombros, virado para a máquina de cabo', 'Segure o puxador do cabo com as duas mãos na altura do peito, mantendo os braços relaxados', 'Posicione a pelve e faça o giro a partir da caixa torácica', 'Gire o tronco enquanto os quadris e a parte inferior do corpo permanecem o mais firmes possível', 'Mantenha o giro suave em vez de jogar os braços pelo corpo', 'Retorne pelo centro antes de girar para o outro lado']),
  ('AwAIlSo', 'Puxada frontal na máquina com pegada invertida', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure os puxadores com as palmas das mãos voltadas para cima, um pouco além da largura dos ombros', 'Sente-se erguido e alinhe os ombros antes de puxar o puxador para baixo', 'Puxe o puxador para baixo levando os cotovelos em direção às costelas; mantenha o tronco firme', 'Mantenha as palmas das mãos na pegada escolhida sem dobrar os punhos para trás', 'Deixe o puxador subir de forma controlada até os braços estarem esticados, depois reajuste os ombros']),
  ('aWedzZX', 'Elevação pélvica com dois pés no banco', array['Sente-se na borda de um banco com as costas apoiadas nele e os pés firmados no chão', 'Posicione as mãos no banco ao lado dos quadris para dar suporte', 'Firme os pés e evite estufar as costelas enquanto os quadris se prepararam para subir', 'Pressione o chão com os pés e levante os quadris até que o tronco e as coxas fiquem alinhados', 'Pare quando os quadris estiverem alinhados com o tronco; não arqueie mais a parte inferior das costas', 'Abaixe os quadris de forma controlada e mantenha os pés firmados para a próxima repetição']),
  ('awG04cF', 'Rosca de punho com foco nos dedos', array['Firme ambos os pés sentado em um banco; segure uma barra com as palmas das mãos voltadas para cima', 'Apoie os antebraços nas coxas, deixando os punhos para fora da borda', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão e do antebraço suportem a carga', 'Deixe a barra rolar em direção às pontas dos dedos, depois feche os dedos firmemente ao redor dela', 'Use uma amplitude curta e suave sem balançar os cotovelos', 'Retorne à posição inicial sem deixar a carga cair das mãos']),
  ('AX1kB0o', 'Elevação pélvica com rotação de quadril', array['Deite-se de costas com os joelhos flexionados e os pés apoiados no chão', 'Posicione as mãos ao lado do corpo para dar suporte', 'Firme os pés e evite estufar as costelas enquanto os quadris se prepararam para subir', 'Pressione o chão com os pés e levante os quadris até que o tronco e as coxas fiquem alinhados', 'Pare quando os quadris estiverem alinhados com o tronco; não arqueie mais a parte inferior das costas', 'Abaixe os quadris de forma controlada e mantenha os pés firmados para a próxima repetição']),
  ('aXcUyKb', 'Desenvolvimento com kettlebell com um braço', array['Fique em pé com os pés na largura dos ombros, segurando um kettlebell com uma das mãos entre as pernas', 'Flexione levemente os joelhos e incline o quadril, abaixando o kettlebell em direção ao chão', 'Contraia o core antes de puxar e mantenha a carga próxima ao corpo', 'Empurre o chão com as pernas e quadris, depois guie o peso até a posição de recebimento', 'Mantenha ambos os ombros nivelados e evite girar o corpo em direção ao braço que está trabalhando', 'Fique totalmente em pé para finalizar, depois abaixe o peso com controle antes da próxima repetição; alterne os lados quando necessário']),
  ('AxFoqAD', 'Elevação de panturrilha unilateral no Hack', array['Ajuste a máquina Hack com um peso adequado', 'Suba na máquina com apenas um pé, mantendo o outro pé fora do chão', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel', 'Suba na ponta dos pés, elevando os calcanhares o mais alto possível sem balançar', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o trabalho', 'Abaixe os calcanhares em um ritmo cadenciado antes de subir novamente; alterne os lados quando necessário']),
  ('aXtJhlg', 'Subida no banco com halteres', array['Posicione-se em frente a um banco ou step segurando um halter em cada mão, com as palmas voltadas para o corpo', 'Coloque o pé direito no banco ou step, garantindo que todo o pé esteja em contato com a superfície', 'Apoie totalmente o pé da frente na plataforma antes de transferir o peso para ele', 'Suba na plataforma empurrando pelo pé da frente para ficar erguido sobre ele', 'Mantenha o pé da frente firme e evite deixar o joelho cair para dentro', 'Empurre o chão com o pé da frente para retornar ao início, depois alterne as pernas conforme planejado']),
  ('ayAHcEm', 'Elevação de ombros inclinada no Smith', array['Ajuste a máquina Smith em uma posição inclinada.', 'Fique de frente para a máquina com uma base estável e os pés na largura dos ombros.', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos.', 'Levante os pesos para longe do tronco até a altura dos ombros, mantendo os cotovelos levemente flexionados.', 'Pare perto da altura dos ombros em vez de encolher os ombros para levantar mais alto.', 'Abaixe os braços lentamente para as laterais sem balançar o peso.']),
  ('B1EVP9F', 'Flexão inclinada', array['Posicione as mãos em uma superfície elevada, como um banco ou degrau, logo acima da largura dos ombros.', 'Estenda as pernas para trás, apoiando-se na ponta dos pés, criando uma linha reta da cabeça aos calcanhares.', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos.', 'Flexione os cotovelos para abaixar o peito, mantendo o corpo em uma linha reta.', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam.', 'Empurre de volta para os braços esticados, mantendo a linha do corpo intacta.'])
